+import { NextRequest, NextResponse } from 'next/server';
+import { isAdminRequest } from '@/lib/adminSession';
+import { normalizeMailConfig, publicMailConfig, validateMailConfig } from '@/lib/mail/config';
+import { readMailConfig, writeMailConfig } from '@/lib/mail/store';
+
+export const runtime = 'nodejs';
+
+function unauthorizedResponse() {
+  return NextResponse.json(
+    { error: '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.', code: 'UNAUTHORIZED' },
+    { status: 401 },
+  );
+}
+
+/** 설정 조회. 비밀번호는 돌려주지 않는다 — `password_set` 으로 "설정됨" 만 알린다. */
+export async function GET(request: NextRequest) {
+  if (!isAdminRequest(request)) return unauthorizedResponse();
+
+  try {
+    return NextResponse.json({ config: publicMailConfig(await readMailConfig()) }, { headers: { 'Cache-Control': 'no-store' } });
+  } catch (error) {
+    console.error('GET /api/mail failed:', error);
+    return NextResponse.json({ error: '메일 설정을 읽지 못했습니다.' }, { status: 500 });
+  }
+}
+
+/**
+ * 설정 저장. 본문에 `password` 가 없거나 빈 문자열이면 기존 비밀번호를 유지하고,
+ * `password_clear: true` 로만 지운다. 저장한 설정은 다음 알림부터 바로 쓰인다.
+ */
+export async function PUT(request: NextRequest) {
+  if (!isAdminRequest(request)) return unauthorizedResponse();
+
+  try {
+    const body: unknown = await request.json();
+    if (typeof body !== 'object' || body === null || Array.isArray(body)) {
+      return NextResponse.json({ error: '요청 본문은 JSON 객체여야 합니다.' }, { status: 400 });
+    }
+
+    const config = normalizeMailConfig(body, await readMailConfig());
+    const issues = validateMailConfig(config);
+    if (issues.length > 0) {
+      return NextResponse.json(
+        { error: '메일 설정이 올바르지 않습니다.', code: 'INVALID_MAIL_CONFIG', details: issues },
+        { status: 400 },
+      );
+    }
+
+    await writeMailConfig(config);
+    return NextResponse.json({ config: publicMailConfig(config) });
+  } catch (error) {
+    if (error instanceof SyntaxError) {
+      return NextResponse.json({ error: '요청 JSON 문법이 올바르지 않습니다.' }, { status: 400 });
+    }
+
+    console.error('PUT /api/mail failed:', error);
+    return NextResponse.json({ error: '메일 설정을 저장하지 못했습니다.' }, { status: 500 });
+  }
+}
