+import { NextRequest, NextResponse } from 'next/server';
+import { readTrackingConfig } from '@/lib/tracking/store';
+
+export const runtime = 'nodejs';
+
+/** 수집 이벤트는 작다. 이보다 큰 본문은 넘기지 않는다. */
+const MAX_BODY_BYTES = 256 * 1024;
+const UPSTREAM_TIMEOUT_MS = 10_000;
+const FORWARDED_REQUEST_HEADERS = ['accept', 'content-type', 'user-agent', 'referer', 'accept-language'];
+const FORWARDED_RESPONSE_HEADERS = ['content-type', 'cache-control', 'etag', 'last-modified'];
+
+/**
+ * Momento 같은 오리진 프록시. 브라우저는 /momento/* 만 보고, 앱이 그 요청을 수집기로 넘긴다.
+ * 그래서 CSP 에 외부 출처를 넣지 않아도 되고, 브라우저에서 수집기가 직접 닿지 않는 망에서도
+ * 동작한다. 추적이 Momento 로 켜져 있고 프록시 사용이 켜진 동안에만 열린다.
+ */
+async function forward(request: NextRequest, path: string[]) {
+  const config = await readTrackingConfig();
+  if (!config.enabled || config.provider !== 'momento' || !config.momento_proxy || !config.momento_url) {
+    return new NextResponse(null, { status: 404 });
+  }
+
+  const contentLength = Number(request.headers.get('content-length'));
+  if (Number.isFinite(contentLength) && contentLength > MAX_BODY_BYTES) {
+    return new NextResponse(null, { status: 413 });
+  }
+
+  let upstream: URL;
+  try {
+    upstream = new URL(path.map(encodeURIComponent).join('/'), `${config.momento_url.replace(/\/+$/, '')}/`);
+    upstream.search = request.nextUrl.search;
+  } catch {
+    return new NextResponse(null, { status: 502 });
+  }
+
+  const headers = new Headers();
+  for (const name of FORWARDED_REQUEST_HEADERS) {
+    const value = request.headers.get(name);
+    if (value) headers.set(name, value);
+  }
+  // 수집기가 방문자 주소를 알 수 있게 넘긴다. 앞단 프록시가 이미 적어 둔 값을 이어 쓴다.
+  const forwardedFor = request.headers.get('x-forwarded-for');
+  if (forwardedFor) headers.set('x-forwarded-for', forwardedFor);
+  headers.set('x-forwarded-host', request.headers.get('host') ?? request.nextUrl.host);
+  headers.set('x-forwarded-proto', request.nextUrl.protocol.replace(':', ''));
+
+  let body: ArrayBuffer | undefined;
+  if (request.method !== 'GET' && request.method !== 'HEAD') {
+    body = await request.arrayBuffer();
+    if (body.byteLength > MAX_BODY_BYTES) return new NextResponse(null, { status: 413 });
+  }
+
+  try {
+    const response = await fetch(upstream, {
+      method: request.method,
+      headers,
+      body,
+      redirect: 'manual',
+      cache: 'no-store',
+      signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
+    });
+    const responseHeaders = new Headers();
+    for (const name of FORWARDED_RESPONSE_HEADERS) {
+      const value = response.headers.get(name);
+      if (value) responseHeaders.set(name, value);
+    }
+    return new NextResponse(response.body, { status: response.status, headers: responseHeaders });
+  } catch (error) {
+    console.error(`Momento 프록시 전달 실패 (${upstream.origin}):`, error);
+    return new NextResponse(null, { status: 502 });
+  }
+}
+
+type Context = { params: Promise<{ path: string[] }> };
+
+export async function GET(request: NextRequest, context: Context) {
+  return forward(request, (await context.params).path);
+}
+
+export async function POST(request: NextRequest, context: Context) {
+  return forward(request, (await context.params).path);
+}
