@@ -0,0 +1,428 @@
+'use client';
+
+import { useCallback, useEffect, useState } from 'react';
+import { AlertCircle, CheckCircle2, Loader2, Mail, RefreshCw, Save, Send } from 'lucide-react';
+import {
+  defaultMailConfig,
+  MAIL_SECURITIES,
+  type MailSecurity,
+  type PublicMailConfig,
+} from '@/lib/mail/config';
+import type { Delivery, DeliveryPage } from '@/lib/mail/store';
+
+interface ValidationIssue {
+  path: string;
+  message: string;
+}
+
+interface Feedback {
+  kind: 'success' | 'error';
+  title: string;
+  details?: ValidationIssue[];
+}
+
+interface MailResponse {
+  config?: PublicMailConfig;
+  error?: string;
+  details?: ValidationIssue[];
+}
+
+interface Props {
+  onUnauthorized: () => void;
+}
+
+/** 화면이 다루는 모양. 비밀번호는 서버가 돌려주지 않으므로 새 값을 적을 때만 채운다. */
+type FormState = PublicMailConfig & { password: string; password_clear: boolean };
+
+const SECURITY_LABELS: Record<MailSecurity, string> = {
+  auto: 'auto — 서버가 알리는 대로 (권장)',
+  none: 'none — 평문',
+  starttls: 'starttls — 반드시 STARTTLS',
+  tls: 'tls — 처음부터 TLS (465)',
+};
+
+const EVENT_SWITCHES: Array<{ key: 'notify_activity_delayed' | 'notify_delay_cleared' | 'notify_task_completed' | 'notify_drill_completed'; label: string; hint: string }> = [
+  { key: 'notify_activity_delayed', label: '지연 발생', hint: '작업이 지연으로 바뀌었을 때' },
+  { key: 'notify_delay_cleared', label: '지연 해소', hint: '지연이던 작업이 다시 진행·완료됐을 때' },
+  { key: 'notify_task_completed', label: '최상위 작업 완료', hint: '다음 작업 팀의 차례가 됐을 때' },
+  { key: 'notify_drill_completed', label: '훈련 완료', hint: '모든 최상위 작업이 완료됐을 때' },
+];
+
+const STATUS_LABEL: Record<Delivery['status'], string> = { queued: '대기', sent: '성공', failed: '실패' };
+const STATUS_CLASS: Record<Delivery['status'], string> = {
+  queued: 'bg-gray-100 text-gray-700',
+  sent: 'bg-emerald-100 text-emerald-800',
+  failed: 'bg-red-100 text-red-800',
+};
+
+const inputClass = 'w-full border border-gray-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-blue-500';
+const labelClass = 'block text-xs font-medium text-gray-600 mb-1';
+
+function toForm(config: PublicMailConfig): FormState {
+  return { ...config, password: '', password_clear: false };
+}
+
+/**
+ * 메일 알림 설정 카드. 설정은 서버의 data/mail.json 에 저장되고 다음 알림부터 바로 쓰인다.
+ * 아래에 시험 발송 단추와 최근 발송 기록이 있다 — 릴레이 설정은 한 번에 맞는 일이 드물다.
+ */
+export default function MailSettings({ onUnauthorized }: Props) {
+  const [form, setForm] = useState<FormState>(() => toForm({ ...defaultMailConfig(), password_set: false }));
+  const [isLoaded, setIsLoaded] = useState(false);
+  const [isSaving, setIsSaving] = useState(false);
+  const [isDirty, setIsDirty] = useState(false);
+  const [feedback, setFeedback] = useState<Feedback | null>(null);
+  const [testRecipient, setTestRecipient] = useState('');
+  const [isTesting, setIsTesting] = useState(false);
+  const [testFeedback, setTestFeedback] = useState<Feedback | null>(null);
+  const [deliveries, setDeliveries] = useState<DeliveryPage | null>(null);
+
+  const loadDeliveries = useCallback(async () => {
+    try {
+      const response = await fetch('/api/mail/deliveries?limit=20', { cache: 'no-store' });
+      if (response.status === 401) {
+        onUnauthorized();
+        return;
+      }
+      if (!response.ok) return;
+      setDeliveries(await response.json() as DeliveryPage);
+    } catch {
+      // 기록은 진단용이다. 잠시 못 읽어도 설정 편집을 막지 않는다.
+    }
+  }, [onUnauthorized]);
+
+  useEffect(() => {
+    let active = true;
+
+    fetch('/api/mail', { cache: 'no-store' })
+      .then(async (response) => {
+        if (!active) return;
+        if (response.status === 401) {
+          onUnauthorized();
+          return;
+        }
+        const result = await response.json() as MailResponse;
+        if (!response.ok || !result.config) {
+          setFeedback({ kind: 'error', title: result.error ?? `메일 설정을 읽지 못했습니다. (HTTP ${response.status})` });
+          return;
+        }
+        setForm(toForm(result.config));
+        void loadDeliveries();
+      })
+      .catch(() => {
+        if (active) setFeedback({ kind: 'error', title: '서버에 연결하지 못해 메일 설정을 읽지 못했습니다.' });
+      })
+      .finally(() => {
+        if (active) setIsLoaded(true);
+      });
+
+    return () => { active = false; };
+  }, [loadDeliveries, onUnauthorized]);
+
+  const update = <K extends keyof FormState>(key: K, value: FormState[K]) => {
+    setForm((previous) => ({ ...previous, [key]: value }));
+    setIsDirty(true);
+    setFeedback(null);
+  };
+
+  const save = async () => {
+    setIsSaving(true);
+    setFeedback(null);
+    try {
+      const { password_set: _passwordSet, ...payload } = form;
+      void _passwordSet;
+      const response = await fetch('/api/mail', {
+        method: 'PUT',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify(payload),
+      });
+      const result = await response.json().catch(() => ({
+        error: `서버 응답을 해석하지 못했습니다. (HTTP ${response.status})`,
+      })) as MailResponse;
+
+      if (!response.ok || !result.config) {
+        setFeedback({
+          kind: 'error',
+          title: result.error ?? `저장에 실패했습니다. (HTTP ${response.status})`,
+          details: result.details,
+        });
+        if (response.status === 401) onUnauthorized();
+        return;
+      }
+
+      setForm(toForm(result.config));
+      setIsDirty(false);
+      setFeedback({
+        kind: 'success',
+        title: result.config.enabled
+          ? '메일 설정을 저장했습니다. 다음 알림부터 이 설정으로 보냅니다.'
+          : '메일 설정을 저장했습니다. 메일 알림은 꺼진 상태입니다.',
+      });
+    } catch (error) {
+      setFeedback({
+        kind: 'error',
+        title: '서버에 연결하지 못해 저장에 실패했습니다.',
+        details: [{ path: 'network', message: error instanceof Error ? error.message : '알 수 없는 네트워크 오류' }],
+      });
+    } finally {
+      setIsSaving(false);
+    }
+  };
+
+  const sendTest = async () => {
+    setIsTesting(true);
+    setTestFeedback(null);
+    try {
+      const response = await fetch('/api/mail/test', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ recipient: testRecipient }),
+      });
+      const result = await response.json().catch(() => ({
+        error: `서버 응답을 해석하지 못했습니다. (HTTP ${response.status})`,
+      })) as { sent?: boolean; error?: string };
+
+      if (response.status === 401) {
+        onUnauthorized();
+        return;
+      }
+      setTestFeedback(response.ok && result.sent
+        ? { kind: 'success', title: `${testRecipient} 로 시험 메일을 보냈습니다. 받은 편지함을 확인하세요.` }
+        : { kind: 'error', title: result.error ?? `시험 발송에 실패했습니다. (HTTP ${response.status})` });
+    } catch (error) {
+      setTestFeedback({
+        kind: 'error',
+        title: `서버에 연결하지 못했습니다: ${error instanceof Error ? error.message : '알 수 없는 네트워크 오류'}`,
+      });
+    } finally {
+      setIsTesting(false);
+      void loadDeliveries();
+    }
+  };
+
+  const renderFeedback = (item: Feedback | null, testId: string) => item && (
+    <div
