@@ -0,0 +1,50 @@
+import { expect, test, type APIResponse } from '@playwright/test';
+
+const adminPassword = 'e2e-admin-password';
+
+function sessionCookieHeader(response: APIResponse) {
+  return response.headersArray()
+    .filter((header) => header.name.toLowerCase() === 'set-cookie')
+    .map((header) => header.value)
+    .find((value) => value.startsWith('cutover_admin_session=')) ?? '';
+}
+
+function hasSecure(setCookie: string) {
+  return setCookie.split(';').some((part) => part.trim().toLowerCase() === 'secure');
+}
+
+test('관리자 세션 쿠키의 Secure 는 요청이 HTTPS 로 왔을 때만 붙는다', async ({ request }) => {
+  // 평문 HTTP(폐쇄망 배포)로 로그인하면 Secure 없이 내려오고 그 쿠키로 세션이 통과한다.
+  expect((await request.get('/api/auth/session')).status()).toBe(401);
+  const plain = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(plain.ok()).toBeTruthy();
+  const plainCookie = sessionCookieHeader(plain);
+  expect(plainCookie).toContain('HttpOnly');
+  expect(plainCookie).toContain('SameSite=strict');
+  expect(hasSecure(plainCookie)).toBe(false);
+  const afterLogin = await request.get('/api/auth/session');
+  expect(afterLogin.ok()).toBeTruthy();
+  expect(await afterLogin.json()).toEqual({ authenticated: true, role: 'admin' });
+
+  // HTTPS 를 종단한 리버스 프록시 뒤에서 온 것처럼 X-Forwarded-Proto 를 붙이면 Secure 가 붙는다.
+  const forwarded = await request.post('/api/auth/login', {
+    data: { pw: adminPassword, role: 'admin' },
+    headers: { 'x-forwarded-proto': 'https' },
+  });
+  expect(forwarded.ok()).toBeTruthy();
+  expect(hasSecure(sessionCookieHeader(forwarded))).toBe(true);
+
+  // 여러 겹 프록시면 첫 값(클라이언트와 맞닿은 쪽)만 본다.
+  const layered = await request.post('/api/auth/login', {
+    data: { pw: adminPassword, role: 'admin' },
+    headers: { 'x-forwarded-proto': 'http, https' },
+  });
+  expect(hasSecure(sessionCookieHeader(layered))).toBe(false);
+
+  // 로그아웃(DELETE) 도 같은 판정으로 지운다.
+  const logout = await request.delete('/api/auth/session', { headers: { 'x-forwarded-proto': 'https' } });
+  expect(logout.ok()).toBeTruthy();
+  const cleared = sessionCookieHeader(logout);
+  expect(cleared).toContain('Max-Age=0');
+  expect(hasSecure(cleared)).toBe(true);
+});
