+async function loginAsAdmin(request: APIRequestContext) {
+  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(response.ok()).toBeTruthy();
+}
+
+async function readData(request: APIRequestContext): Promise<DashboardData> {
+  return (await request.get('/api/activities')).json();
+}
+
+const tree: Activity[] = [
+  { id: 'root', parentId: null, level: 1, time: '23:30 ~ 00:40', title: '[E2E] 덮어쓰기 최상위', status: '대기' },
+  { id: 'child', parentId: 'root', level: 2, time: '23:30 ~ 00:00', title: '[E2E] 덮어쓰기 하위', status: '대기' },
+];
+
+/** 관리 화면을 열어 둔 사이 "다른 관리자" 가 넣는 변경. 제목과 상태 둘 다 바꾼다. */
+const otherAdminTree: Activity[] = [
+  tree[0],
+  { ...tree[1], title: '[E2E] 다른 관리자가 바꾼 하위', status: '지연' },
+];
+
+let original: DashboardData;
+
+test.beforeEach(async ({ request }) => {
+  original = await readData(request);
+  await loginAsAdmin(request);
+  const imported = await request.put('/api/activities', { data: { activities: tree } });
+  expect(imported.status(), await imported.text()).toBe(200);
+});
+
+test.afterEach(async ({ request }) => {
+  await loginAsAdmin(request);
+  await request.put('/api/activities', {
+    data: { activities: original.activities, dashboardTitle: original.dashboardTitle },
+  });
+});
+
+async function loginThroughUi(page: Page) {
+  await page.goto('/admin');
+  await page.getByPlaceholder('관리자 비밀번호').fill(adminPassword);
+  await page.getByRole('button', { name: '로그인' }).click();
+  await expect(page.getByText('[E2E] 덮어쓰기 하위', { exact: true })).toBeVisible();
+}
+
+/**
+ * GET 만 고정된 스냅샷으로 돌려준다(SWR 1초 폴링이 더 새 값을 가져오지 못한다).
+ * PUT 은 route.fallback() 으로 실제 서버까지 보낸다 — 손으로 만든 대역이 아니다.
+ */
+async function freezeGet(page: Page, snapshot: DashboardData) {
+  await page.route('**/api/activities', async (route) => {
+    if (route.request().method() !== 'GET') return route.fallback();
+    await route.fulfill({
+      status: 200,
+      contentType: 'application/json',
+      body: JSON.stringify(snapshot),
+    });
+  });
+}
+
+/** GET 만 500 으로 돌려준다(읽기 실패 배너 상태). PUT 은 실제 서버까지 보낸다. */
+async function failEveryGet(page: Page) {
+  await page.route('**/api/activities', async (route) => {
+    if (route.request().method() !== 'GET') return route.fallback();
+    await route.fulfill({
+      status: 500,
+      contentType: 'application/json',
+      body: JSON.stringify({ activities: [], dashboardTitle: '', visitorCount: 0, lastUpdated: '', error: '저장된 상황판 데이터를 읽지 못했습니다.' }),
+    });
+  });
+}
+
+/** 트리 행의 상태 드롭다운만. 설정 카드의 select 는 '완료' 옵션이 없다. */
+function statusSelects(page: Page) {
+  return page.locator('select').filter({ has: page.locator('option[value="완료"]') });
+}
+
+async function changeStatus(page: Page, index: number, status: string) {
+  const putDone = page.waitForResponse((r) => r.url().includes('/api/activities') && r.request().method() === 'PUT');
+  await statusSelects(page).nth(index).selectOption(status);
+  return putDone;
+}
+
+test('읽기가 죽어 있어도 혼자 하는 연속 저장은 409 가 되지 않는다', async ({ page }) => {
+  test.setTimeout(90_000);
+  await loginThroughUi(page);
+  await expect(statusSelects(page)).toHaveCount(2);
+
+  // GET 이 계속 500 — 관리 화면은 폴링으로 새 스냅샷을 받을 수 없다.
+  await failEveryGet(page);
+  await expect(page.getByTestId('admin-load-error')).toBeVisible({ timeout: 30_000 });
+
+  // 다른 관리자는 없다. 같은 사람이 두 번 저장할 뿐이다.
+  expect((await changeStatus(page, 1, '진행')).status()).toBe(200);
+  expect((await changeStatus(page, 1, '완료')).status()).toBe(200);
+  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);
+
+  // 판정은 라우팅을 푼 뒤의 실제 GET 으로만 한다.
+  await page.unroute('**/api/activities');
+  expect((await readData(page.request)).activities.find((a) => a.id === 'child')?.status).toBe('완료');
+});
+
+test('오래된 스냅샷으로 상태를 바꾸면 409 가 뜨고 다른 관리자의 변경이 되돌아가지 않는다', async ({ page }) => {
+  await loginThroughUi(page);
+  await expect(statusSelects(page)).toHaveCount(2);
+
+  // 화면이 보고 있는 스냅샷을 이 시점에 고정한다.
+  await freezeGet(page, await readData(page.request));
+
+  // 같은 브라우저 컨텍스트로 "다른 관리자" 변경을 실제로 저장한다.
+  const other = await page.request.put('/api/activities', { data: { activities: otherAdminTree } });
+  expect(other.status(), await other.text()).toBe(200);
+  const afterOther = await other.json() as DashboardData;
+
+  const putDone = page.waitForResponse((r) => r.url().includes('/api/activities') && r.request().method() === 'PUT');
+  await statusSelects(page).nth(1).selectOption('완료');
+  expect((await putDone).status()).toBe(409);
+
+  await expect(page.getByTestId('admin-save-error')).toContainText('다른 곳에서 상황판이 먼저 바뀌어 저장하지 않았습니다');
+
+  // 판정은 라우팅을 풀고 읽은 GET 으로만 한다(폴링을 증거로 쓰지 않는다).
+  await page.unroute('**/api/activities');
+  const saved = await readData(page.request);
+  const child = saved.activities.find((a) => a.id === 'child');
+  expect(child?.title).toBe(otherAdminTree[1].title);
+  expect(child?.status).toBe('지연');
+  // 아무것도 쓰지 않았으므로 lastUpdated 도 다른 관리자의 쓰기 시점 그대로다.
+  expect(saved.lastUpdated).toBe(afterOther.lastUpdated);
+});
+
+test('expectedLastUpdated 가 저장된 값과 다른 전체 배열 PUT 은 409 STALE_SNAPSHOT 이고 아무것도 쓰지 않는다', async ({ request }) => {
+  const before = await readData(request);
+
+  const response = await request.put('/api/activities', {
+    data: { activities: otherAdminTree, expectedLastUpdated: '2020-01-01T00:00:00.000Z' },
+  });
+  expect(response.status(), await response.text()).toBe(409);
+  const result = await response.json() as { error?: string; code?: string };
+  expect(result.code).toBe('STALE_SNAPSHOT');
+  expect(typeof result.error).toBe('string');
+
+  const after = await readData(request);
+  expect(after.activities).toEqual(before.activities);
+  expect(after.lastUpdated).toBe(before.lastUpdated);
+});
+
+test('expectedLastUpdated 가 맞거나 아예 없는 전체 배열 PUT 은 그대로 200 이다', async ({ request }) => {
+  const before = await readData(request);
+
+  // 맞는 경우
+  const matching = await request.put('/api/activities', {
+    data: { activities: otherAdminTree, expectedLastUpdated: before.lastUpdated },
+  });
+  expect(matching.status(), await matching.text()).toBe(200);
+  expect((await readData(request)).activities.find((a) => a.id === 'child')?.status).toBe('지연');
+
+  // 필드가 없는 기존 계약(여러 spec 의 셋업·복원이 이 모양을 쓴다)
+  const withoutField = await request.put('/api/activities', { data: { activities: tree } });
+  expect(withoutField.status(), await withoutField.text()).toBe(200);
+  expect((await readData(request)).activities.find((a) => a.id === 'child')?.status).toBe('대기');
+});
