@@ -0,0 +1,143 @@
+import { expect, test, type APIRequestContext, type Page } from '@playwright/test';
+
+const adminPassword = 'e2e-admin-password';
+const userPassword = 'e2e-user-password';
+
+interface Activity {
+  id: string;
+  parentId: string | null;
+  level: number;
+  time: string;
+  title: string;
+  status: string;
+}
+
+/**
+ * GET /api/activities 가 읽기에 실패했을 때 실제로 돌려주는 본문 모양 그대로
+ * (app/api/activities/route.ts 의 catch 분기). 정상 JSON 이라 파싱은 성공하므로,
+ * 화면이 res.ok 를 보지 않으면 이 빈 배열이 "등록된 작업 없음" 으로 그려진다.
+ */
+const failureBody = {
+  activities: [],
+  dashboardTitle: '2026 재해복구 모의훈련 대시보드',
+  visitorCount: 0,
+  lastUpdated: '2026-10-04T00:00:00.000Z',
+  error: '저장된 상황판 데이터를 읽지 못했습니다.',
+};
+
+const rowTitle = '[E2E] 읽기실패 확인용 최상위';
+
+const tree: Activity[] = [
+  { id: 'load-failure-root', parentId: null, level: 1, time: '23:30 ~ 00:40', title: rowTitle, status: '진행' },
+];
+
+let original: { activities: Activity[]; dashboardTitle: string };
+
+async function loginAsAdmin(request: APIRequestContext) {
+  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(response.ok()).toBeTruthy();
+}
+
+test.beforeEach(async ({ request }) => {
+  original = await (await request.get('/api/activities')).json();
+  await loginAsAdmin(request);
+  const imported = await request.put('/api/activities', { data: { activities: tree } });
+  expect(imported.status(), await imported.text()).toBe(200);
+});
+
+test.afterEach(async ({ request }) => {
+  await loginAsAdmin(request);
+  await request.put('/api/activities', {
+    data: { activities: original.activities, dashboardTitle: original.dashboardTitle },
+  });
+});
+
+/** GET 만 500 으로 돌려준다. 관리자 PUT 은 그대로 통과시킨다. */
+async function failEveryGet(page: Page) {
+  await page.route('**/api/activities', async (route) => {
+    if (route.request().method() !== 'GET') return route.fallback();
+    await route.fulfill({
+      status: 500,
+      contentType: 'application/json',
+      body: JSON.stringify(failureBody),
+    });
+  });
+}
+
+async function loginAsUser(page: Page) {
+  await page.getByPlaceholder('비밀번호 입력').fill(userPassword);
+  await page.getByRole('button', { name: '로그인' }).click();
+}
+
+test('첫 로드부터 GET 이 500 이면 표준 상황판은 빈 트리 대신 읽기 실패 화면을 보여 준다', async ({ page }) => {
+  await failEveryGet(page);
+  await page.goto('/');
+  await loginAsUser(page);
+
+  const failure = page.getByTestId('dashboard-load-error');
+  await expect(failure).toBeVisible();
+  await expect(failure).toContainText('저장된 상황판 데이터를 읽지 못했습니다.');
+
+  // "0% 완료 (0/0)" 빈 상황판을 그리지 않는다 — 통계줄·시계가 들어 있는 헤더 자체가 없다.
+  await expect(page.getByTestId('mobile-clock')).toHaveCount(0);
+});
+
+test('표준 상황판은 성공 후 폴링이 500 으로 바뀌어도 직전 트리를 유지하고 경고만 띄운다', async ({ page }) => {
+  test.setTimeout(90_000);
+
+  await page.goto('/');
+  await loginAsUser(page);
+  const row = page.getByText(rowTitle, { exact: true });
+  await expect(row).toBeVisible();
+
+  await failEveryGet(page);
+  const stale = page.getByTestId('dashboard-stale-warning');
+  await expect(stale).toBeVisible({ timeout: 30_000 });
+  await expect(stale).toContainText('최신이 아닐 수 있습니다');
+  // 훈련 중 화면을 통째로 비우지 않는다.
+  await expect(row).toBeVisible();
+  await expect(page.getByTestId('dashboard-load-error')).toHaveCount(0);
+
+  await page.unroute('**/api/activities');
+  await expect(stale).toHaveCount(0, { timeout: 30_000 });
+  await expect(row).toBeVisible();
+});
+
+test('전광판도 첫 로드 실패에는 오류 화면을, 폴링 실패에는 경고 배너를 보여 준다', async ({ page }) => {
+  test.setTimeout(90_000);
+
+  await failEveryGet(page);
+  await page.goto('/pc');
+  await loginAsUser(page);
+  await expect(page.getByTestId('dashboard-load-error')).toContainText('저장된 상황판 데이터를 읽지 못했습니다.');
+
+  // 가로채기를 풀면 전광판이 정상 트리로 복귀한다.
+  await page.unroute('**/api/activities');
+  const row = page.getByText(rowTitle, { exact: true });
+  await expect(row).toBeVisible({ timeout: 30_000 });
+
+  // 그 뒤 폴링이 다시 500 이 되면 트리를 유지한 채 경고만 띄운다.
+  await failEveryGet(page);
+  const stale = page.getByTestId('dashboard-stale-warning');
+  await expect(stale).toBeVisible({ timeout: 30_000 });
+  await expect(row).toBeVisible();
+});
+
+test('관리자 화면은 읽기 실패를 저장 실패 배너와 구분되는 admin-load-error 로 남긴다', async ({ page }) => {
+  test.setTimeout(90_000);
+
+  await page.goto('/admin');
+  await page.getByPlaceholder('관리자 비밀번호').fill(adminPassword);
+  await page.getByRole('button', { name: '로그인' }).click();
+  await expect(page.getByText(rowTitle, { exact: true })).toBeVisible();
+
+  await failEveryGet(page);
+  const loadError = page.getByTestId('admin-load-error');
+  await expect(loadError).toBeVisible({ timeout: 30_000 });
+  await expect(loadError).toContainText('저장된 상황판 데이터를 읽지 못했습니다.');
+  // 저장 실패 배너는 건드리지 않는다.
+  await expect(page.getByTestId('admin-save-error')).toHaveCount(0);
+
+  await page.unroute('**/api/activities');
+  await expect(loadError).toHaveCount(0, { timeout: 30_000 });
+});
