+import fs from 'node:fs/promises';
+import path from 'node:path';
+import { expect, test, type APIRequestContext } from '@playwright/test';
+import { startFakeRelay, unusedPort, type FakeRelay } from '../lib/mail/testing';
+
+const adminPassword = 'e2e-admin-password';
+const mailConfigPath = path.join(process.cwd(), 'test-results', 'e2e-data', 'mail.json');
+
+interface Activity {
+  id: string;
+  parentId: string | null;
+  level: number;
+  time: string;
+  title: string;
+  status: string;
+}
+
+interface Delivery {
+  event: string;
+  recipient: string;
+  subject: string;
+  status: string;
+  attempts: number;
+  error_message: string;
+}
+
+async function loginAsAdmin(request: APIRequestContext) {
+  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(response.ok()).toBeTruthy();
+}
+
+async function activities(request: APIRequestContext): Promise<Activity[]> {
+  return (await (await request.get('/api/activities')).json()).activities;
+}
+
+/** 액티비티 하나의 상태를 바꾸는 저장. 응답에 걸린 시간을 함께 돌려준다 — 메일이 요청을 막지 않는지 본다. */
+async function setStatus(request: APIRequestContext, id: string, status: string) {
+  const current = await activities(request);
+  const started = Date.now();
+  const response = await request.put('/api/activities', {
+    data: { activities: current.map((activity) => (activity.id === id ? { ...activity, status } : activity)), targetId: id, newStatus: status },
+  });
+  expect(response.status(), await response.text()).toBe(200);
+  return Date.now() - started;
+}
+
+async function deliveries(request: APIRequestContext): Promise<{ items: Delivery[]; summary: { total: number } }> {
+  const response = await request.get('/api/mail/deliveries?limit=50');
+  expect(response.status()).toBe(200);
+  return response.json();
+}
+
+async function waitForDeliveries(request: APIRequestContext, predicate: (items: Delivery[]) => boolean, timeoutMs = 15_000) {
+  const deadline = Date.now() + timeoutMs;
+  let page = await deliveries(request);
+  while (!predicate(page.items) && Date.now() < deadline) {
+    await new Promise((resolve) => setTimeout(resolve, 250));
+    page = await deliveries(request);
+  }
+  return page;
+}
+
+function decodeSubject(raw: string) {
+  const line = raw.split('\r\n\r\n')[0].split('\r\n').join('\n').replace(/\n /g, '').split('\n').find((header) => header.startsWith('Subject: ')) ?? '';
+  return line.slice('Subject: '.length).replace(/=\?UTF-8\?B\?([^?]+)\?=/g, (_match, encoded: string) => Buffer.from(encoded, 'base64').toString('utf-8'));
+}
+
+let relay: FakeRelay;
+let original: Activity[];
+
+test.beforeAll(async ({ request }) => {
+  relay = await startFakeRelay({ auth: { username: 'mailer', password: 's3cret' } });
+  original = await activities(request);
+});
+
+test.afterAll(async ({ request }) => {
+  await relay.close();
+  await loginAsAdmin(request);
+  await request.put('/api/mail', { data: { enabled: false } });
+  await request.put('/api/activities', { data: { activities: original } });
+});
+
+test('기본값은 꺼짐: 상태를 바꿔도 아무것도 나가지 않고 설정 파일도 생기지 않는다', async ({ request }) => {
+  expect((await request.get('/api/mail')).status()).toBe(401);
+  expect((await request.put('/api/mail', { data: { enabled: true } })).status()).toBe(401);
+  expect((await request.post('/api/mail/test', { data: { recipient: 'x@y.z' } })).status()).toBe(401);
+
+  await loginAsAdmin(request);
+  const { config } = await (await request.get('/api/mail')).json();
+  expect(config.enabled).toBe(false);
+  expect(config.smtp_port).toBe(25);
+  expect(config.security).toBe('auto');
+  expect(config.password_set).toBe(false);
+  expect(config).not.toHaveProperty('password');
+
+  const target = original.find((activity) => activity.status !== '지연')!;
+  await setStatus(request, target.id, '지연');
+  await new Promise((resolve) => setTimeout(resolve, 1000));
+  expect((await deliveries(request)).summary.total).toBe(0);
+  await expect(fs.access(mailConfigPath)).rejects.toThrow();
+
+  // 시험 발송도 꺼져 있으면 이유를 말하고 보내지 않는다.
+  const testSend = await request.post('/api/mail/test', { data: { recipient: 'me@corp.example' } });
+  expect(testSend.status()).toBe(409);
+  expect((await testSend.json()).error).toContain('꺼져');
+});
+
+test('켜면 지연 알림이 릴레이로 나가고 기록에 남으며 비밀번호는 되읽히지 않는다', async ({ page }) => {
+  const request = page.request;
+  await loginAsAdmin(request);
+
+  // 앞 시험이 지연으로 둔 것을 메일이 꺼진 채로 되돌린다.
+  const target = original.find((activity) => activity.status !== '지연')!;
+  await setStatus(request, target.id, '진행');
+
+  const invalid = await request.put('/api/mail', { data: { enabled: true, recipients: 'not an address' } });
+  expect(invalid.status()).toBe(400);
+  expect((await invalid.json()).details.map((issue: { path: string }) => issue.path)).toEqual(
+    expect.arrayContaining(['smtp_host', 'from_address', 'recipients']),
+  );
+
+  const saved = await request.put('/api/mail', {
+    data: {
+      enabled: true,
+      smtp_host: relay.host,
+      smtp_port: relay.port,
+      username: 'mailer',
+      password: 's3cret',
+      from_address: 'cutover@corp.example',
+      from_name: '상황판',
+      base_url: 'http://cutover.corp.example',
+      recipients: 'pmo@corp.example\nops@corp.example',
+    },
