+  expect(saved.status(), await saved.text()).toBe(200);
+  const savedConfig = (await saved.json()).config;
+  expect(savedConfig.password_set).toBe(true);
+  expect(JSON.stringify(savedConfig)).not.toContain('s3cret');
+  expect(JSON.stringify(await (await request.get('/api/mail')).json())).not.toContain('s3cret');
+
+  // 비밀번호를 빼고 다시 저장해도 기존 값이 남는다.
+  const resaved = await request.put('/api/mail', { data: { ...savedConfig, from_name: '상황판 알림' } });
+  expect((await resaved.json()).config.password_set).toBe(true);
+
+  const before = relay.received.length;
+  await setStatus(request, target.id, '지연');
+
+  const page1 = await waitForDeliveries(request, (items) => items.filter((item) => item.status === 'sent').length >= 2);
+  const sent = page1.items.filter((item) => item.status === 'sent');
+  expect(sent.map((item) => item.recipient).sort()).toEqual(['ops@corp.example', 'pmo@corp.example']);
+  expect(sent[0].event).toBe('activity.delayed');
+  expect(sent[0].subject).toContain(`지연: ${target.title}`);
+  expect(sent[0].attempts).toBe(1);
+  expect(sent[0]).not.toHaveProperty('body');
+
+  expect(relay.received.length - before).toBe(2);
+  const mail = relay.received[relay.received.length - 1];
+  expect(mail.from).toBe('cutover@corp.example');
+  expect(decodeSubject(mail.data)).toContain(`지연: ${target.title}`);
+  expect(mail.data).toContain('바로 열기: http://cutover.corp.example/pc');
+  expect(mail.data).toContain('Auto-Submitted: auto-generated');
+  expect(relay.authAttempts).toContain('mailer:s3cret');
+
+  // 관리 화면(세션 쿠키가 있어 바로 열린다): 비밀번호는 "설정됨" 으로만 보이고, 시험 발송 단추가 그 자리에서 결과를 보여 준다.
+  await page.goto('/admin');
+  await expect(page.getByRole('heading', { name: '메일 알림 (SMTP 릴레이)' })).toBeVisible();
+  await expect(page.getByTestId('mail-enabled')).toBeChecked();
+  await expect(page.getByTestId('mail-password-state')).toHaveText('설정됨');
+  await expect(page.getByTestId('mail-password')).toHaveValue('');
+  await expect(page.getByTestId('mail-delivery').first()).toContainText('성공');
+
+  const beforeTest = relay.received.length;
+  await page.getByTestId('mail-test-recipient').fill('me@corp.example');
+  await page.getByTestId('mail-test-send').click();
+  await expect(page.getByTestId('mail-test-success')).toContainText('me@corp.example');
+  expect(relay.received.length).toBe(beforeTest + 1);
+  expect(relay.received[relay.received.length - 1].to).toEqual(['me@corp.example']);
+  await expect(page.getByTestId('mail-delivery').first()).toContainText('SMTP 발송 테스트');
+});
+
+test('릴레이가 죽어 있어도 요청은 정상으로 끝나고 실패가 기록되며, 스위치를 끄면 그 종류만 멎는다', async ({ request }) => {
+  await loginAsAdmin(request);
+  const deadPort = await unusedPort();
+  const current = (await (await request.get('/api/mail')).json()).config;
+  const dead = { ...current, smtp_port: deadPort, username: '', password_clear: true, recipients: 'pmo@corp.example', notify_delay_cleared: false };
+  expect((await request.put('/api/mail', { data: dead })).status()).toBe(200);
+
+  const target = original.find((activity) => activity.status !== '지연')!;
+  await setStatus(request, target.id, '진행');
+  const totalBefore = (await deliveries(request)).summary.total;
+  const elapsed = await setStatus(request, target.id, '지연');
+  expect(elapsed).toBeLessThan(3000);
+
+  const failed = await waitForDeliveries(request, (items) => items.some((item) => item.status === 'failed' && item.recipient === 'pmo@corp.example'));
+  const record = failed.items.find((item) => item.status === 'failed' && item.recipient === 'pmo@corp.example')!;
+  expect(record.attempts).toBe(2);
+  expect(record.error_message).toContain('SMTP 연결 실패');
+  expect(failed.summary.total).toBe(totalBefore + 1);
+
+  const testSend = await request.post('/api/mail/test', { data: { recipient: 'me@corp.example' } });
+  expect(testSend.status()).toBe(502);
+  expect((await testSend.json()).error).toContain('SMTP 연결 실패');
+
+  // 지연 스위치를 끄면 지연은 멎고 다른 종류는 그대로다.
+  const afterTest = (await deliveries(request)).summary.total;
+  expect((await request.put('/api/mail', { data: { ...dead, notify_activity_delayed: false } })).status()).toBe(200);
