+import http from 'node:http';
+import type { AddressInfo } from 'node:net';
+import { expect, test, type APIRequestContext, type Page } from '@playwright/test';
+
+const adminPassword = 'e2e-admin-password';
+
+/** 수집기 흉내. tracker.js 를 내려 주고 /collect 로 오는 이벤트를 기억한다. */
+interface CollectorHit {
+  method: string;
+  path: string;
+  body: string;
+  headers: http.IncomingHttpHeaders;
+}
+
+let collector: http.Server;
+let collectorUrl: string;
+const hits: CollectorHit[] = [];
+
+test.beforeAll(async () => {
+  collector = http.createServer((request, response) => {
+    let body = '';
+    request.on('data', (chunk) => { body += chunk; });
+    request.on('end', () => {
+      hits.push({ method: request.method ?? '', path: request.url ?? '', body, headers: request.headers });
+      if (request.url === '/tracker.js') {
+        response.writeHead(200, { 'Content-Type': 'application/javascript' });
+        response.end(`(function(){var s=document.currentScript;var e=s.getAttribute('data-endpoint');
+          window.__momentoLoaded=true;
+          fetch(e+'/collect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({site:s.getAttribute('data-site-id'),page:location.pathname})});
+        })();`);
+        return;
+      }
+      response.writeHead(204);
+      response.end();
+    });
+  });
+  await new Promise<void>((resolve) => collector.listen(0, '127.0.0.1', resolve));
+  collectorUrl = `http://127.0.0.1:${(collector.address() as AddressInfo).port}`;
+});
+
+test.afterAll(async () => {
+  await new Promise<void>((resolve) => collector.close(() => resolve()));
+});
+
+function scriptDirective(policy: string) {
+  return policy.split(';').map((part) => part.trim()).find((part) => part.startsWith('script-src ')) ?? '';
+}
+
+function nonceOf(policy: string) {
+  return scriptDirective(policy).match(/'nonce-([^']+)'/)?.[1] ?? '';
+}
+
+function snippetTags(html: string) {
+  return [...html.matchAll(/<script[^>]*data-tracking-snippet[^>]*>/g)].map((match) => match[0]);
+}
+
+async function loginAsAdmin(request: APIRequestContext) {
+  const response = await request.post('/api/auth/login', { data: { pw: adminPassword, role: 'admin' } });
+  expect(response.ok()).toBeTruthy();
+}
+
+async function saveTracking(request: APIRequestContext, config: Record<string, unknown>) {
+  const response = await request.put('/api/tracking', { data: config });
+  expect(response.status(), await response.text()).toBe(200);
+  return response.json();
+}
+
+function cspErrors(page: Page) {
+  const errors: string[] = [];
+  page.on('console', (message) => {
+    if (message.type() === 'error' && /Content Security Policy/i.test(message.text())) errors.push(message.text());
+  });
+  return errors;
+}
+
+test('기본값은 꺼짐: 스니펫이 없고 정책은 nonce 와 앱 오리진만 허용한다', async ({ page }) => {
+  const request = page.request;
+  const errors = cspErrors(page);
+  const response = await request.get('/pc');
+  const policy = response.headers()['content-security-policy'] ?? '';
+  const html = await response.text();
+
+  expect(nonceOf(policy)).not.toBe('');
+  expect(scriptDirective(policy)).toBe(`script-src 'self' 'nonce-${nonceOf(policy)}' 'unsafe-eval'`);
+  expect(policy).not.toContain('report-uri');
+  expect(snippetTags(html)).toHaveLength(0);
+
+  const apiResponse = await request.get('/api/activities');
+  expect(apiResponse.headers()['content-security-policy']).toBe("default-src 'none'; frame-ancestors 'none'");
+  expect((await request.get('/momento/tracker.js')).status()).toBe(404);
+  expect((await request.put('/api/tracking', { data: { enabled: true } })).status()).toBe(401);
+  expect((await request.get('/api/tracking')).status()).toBe(401);
+
+  // 기본 정책이 상황판 자체를 막지 않아야 한다.
+  await page.context().addCookies([{ name: 'cutover_user', value: 'true', url: 'http://127.0.0.1:3100' }]);
+  await page.goto('/pc');
+  await expect(page.getByText('재해복구 모의훈련', { exact: false }).first()).toBeVisible();
+  await page.goto('/');
+  await page.waitForLoadState('networkidle');
+  expect(errors).toEqual([]);
+});
+
+test('Momento 를 켜면 nonce 가 붙은 스니펫이 head 에 들어가고 같은 오리진 프록시로 수집이 들어온다', async ({ page }) => {
+  const request = page.request;
+  await loginAsAdmin(request);
+  const errors = cspErrors(page);
+
+  // 8KB 를 넘는 스니펫은 저장되지 않는다.
+  const tooLarge = await request.put('/api/tracking', {
+    data: { enabled: true, provider: 'custom', custom_snippet: `<script>${'x'.repeat(8 * 1024)}</script>` },
+  });
+  expect(tooLarge.status()).toBe(400);
+  expect((await tooLarge.json()).details[0].path).toBe('custom_snippet');
+
+  await saveTracking(request, {
+    enabled: true,
+    provider: 'momento',
+    momento_url: collectorUrl,
+    momento_site_id: 'cutover-e2e',
+    momento_proxy: true,
+  });
+
+  const response = await request.get('/pc');
+  const policy = response.headers()['content-security-policy'] ?? '';
+  const html = await response.text();
+  const nonce = nonceOf(policy);
+  expect(nonce).not.toBe('');
+  expect(policy).toContain('report-uri /api/csp-report');
+  expect(policy).not.toContain(collectorUrl);
+  expect(scriptDirective(policy)).not.toContain('unsafe-inline');
+
+  const tags = snippetTags(html);
+  expect(tags).toHaveLength(1);
+  expect(tags[0]).toContain(`nonce="${nonce}"`);
+  expect(tags[0]).toContain('src="/momento/tracker.js"');
+  expect(tags[0]).toContain('data-endpoint="/momento"');
+  expect(tags[0]).toContain('data-site-id="cutover-e2e"');
+  expect(html.indexOf(tags[0])).toBeLessThan(html.indexOf('<body'));
+
+  // 요청마다 nonce 가 다르다.
+  const second = await request.get('/pc');
+  expect(nonceOf(second.headers()['content-security-policy'] ?? '')).not.toBe(nonce);
+
+  // 관리 화면과 API 에는 붙지 않는다.
+  const adminHtml = await (await request.get('/admin')).text();
+  expect(snippetTags(adminHtml)).toHaveLength(0);
+  expect(snippetTags(await (await request.get('/api/activities')).text())).toHaveLength(0);
+
+  // 실제 브라우저에서 스니펫이 실행되고 프록시를 거쳐 수집기에 이벤트가 닿는다.
+  hits.length = 0;
+  await page.context().addCookies([{ name: 'cutover_user', value: 'true', url: 'http://127.0.0.1:3100' }]);
+  await page.goto('/pc');
+  await expect.poll(() => page.evaluate(() => (window as unknown as { __momentoLoaded?: boolean }).__momentoLoaded)).toBe(true);
+  await expect.poll(() => hits.some((hit) => hit.path === '/collect')).toBe(true);
+  const collectHit = hits.find((hit) => hit.path === '/collect');
+  expect(collectHit?.method).toBe('POST');
+  expect(JSON.parse(collectHit?.body ?? '{}')).toEqual({ site: 'cutover-e2e', page: '/pc' });
+  expect(collectHit?.headers['x-forwarded-host']).toBe('127.0.0.1:3100');
+  expect(errors).toEqual([]);
+
+  // placement=body 는 body 안에 들어간다.
+  await saveTracking(request, {
+    enabled: true, provider: 'momento', momento_url: collectorUrl, momento_site_id: 'cutover-e2e', placement: 'body',
+  });
+  const bodyResponse = await request.get('/pc');
+  const bodyHtml = await bodyResponse.text();
+  const bodyTags = snippetTags(bodyHtml);
+  expect(bodyTags).toHaveLength(1);
+  expect(bodyTags[0]).toContain(`nonce="${nonceOf(bodyResponse.headers()['content-security-policy'] ?? '')}"`);
+  expect(bodyHtml.indexOf(bodyTags[0])).toBeGreaterThan(bodyHtml.indexOf('<body'));
+  hits.length = 0;
+  await page.goto('/pc');
+  await expect.poll(() => hits.some((hit) => hit.path === '/collect')).toBe(true);
+  expect(errors).toEqual([]);
+
+  // 프록시를 끄면 수집기 출처가 정책에 등장한다.
+  await saveTracking(request, {
+    enabled: true, provider: 'momento', momento_url: collectorUrl, momento_site_id: 'cutover-e2e', momento_proxy: false,
+  });
+  const directPolicy = (await request.get('/pc')).headers()['content-security-policy'] ?? '';
+  expect(scriptDirective(directPolicy)).toContain(collectorUrl);
+  expect(directPolicy).toContain(`connect-src 'self' ws: wss: ${collectorUrl}`);
+  expect((await request.get('/momento/tracker.js')).status()).toBe(404);
+
+  // 끄면 정책이 원래대로 좁아진다.
+  await saveTracking(request, { enabled: false, provider: 'momento', momento_url: collectorUrl, momento_site_id: 'cutover-e2e' });
+  const offPolicy = (await request.get('/pc')).headers()['content-security-policy'] ?? '';
+  expect(offPolicy).not.toContain(collectorUrl);
+  expect(offPolicy).not.toContain('report-uri');
+  expect(snippetTags(await (await request.get('/pc')).text())).toHaveLength(0);
+});
+
+test('정책 위반 신고가 기록되고 관리 화면에서 허용 목록에 더할 수 있다', async ({ page }) => {
+  const request = page.request;
+  await loginAsAdmin(request);
+  await saveTracking(request, {
+    enabled: true,
+    provider: 'custom',
+    custom_snippet: '<script async src="https://tracker.corp.example/t.js"></script>',
+    include_admin: false,
+  });
+  await request.delete('/api/tracking/violations');
+
