+  expect((await report('https://pixel.corp.example/p.gif?id=1', 'img-src')).status()).toBe(204);
+  expect((await report('https://pixel.corp.example/p.gif?id=2', 'img-src')).status()).toBe(204);
+  expect((await report('https://tracker.corp.example/collect', 'connect-src')).status()).toBe(204);
+  expect((await report('chrome-extension://abc/x.js', 'script-src')).status()).toBe(204);
+
+  const listed = await (await request.get('/api/tracking/violations')).json();
+  expect(listed.violations).toHaveLength(2);
+  const pixel = listed.violations.find((item: { origin: string }) => item.origin === 'https://pixel.corp.example');
+  expect(pixel).toMatchObject({ directive: 'img-src', page: '/pc', count: 2, allowed: false });
+  expect(listed.violations.find((item: { origin: string }) => item.origin === 'https://tracker.corp.example')?.allowed).toBe(true);
+
+  // 관리 화면에서 한 번 눌러 허용 목록에 넣는다.
