+  await expect(page.getByTestId('tracking-enabled')).toBeChecked();
+  await expect(page.getByTestId('tracking-provider')).toHaveValue('custom');
+  const pixelRow = page.getByTestId('tracking-violation').filter({ hasText: 'https://pixel.corp.example' });
