+  await pixelRow.getByRole('button', { name: '허용 목록에 추가' }).click();
+  await expect(page.getByTestId('tracking-success')).toContainText('저장했습니다');
+  await expect(page.getByTestId('tracking-allowed-hosts')).toHaveValue('https://pixel.corp.example');
+  await expect(pixelRow).toContainText('이미 허용됨');
+
+  const policy = (await request.get('/pc')).headers()['content-security-policy'] ?? '';
+  expect(policy).toContain('img-src \'self\' data: blob: https://tracker.corp.example https://pixel.corp.example');
+
+  // 잘못된 값은 화면에 이유가 보인다.
+  await page.getByTestId('tracking-allowed-hosts').fill("https://ok.example; script-src 'unsafe-inline'");
