+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import { resolveAdminCookieSecure } from './adminSession.ts';
+
+describe('관리자 세션 쿠키 Secure 판정', () => {
+  it('설정이 없으면 요청 프로토콜을 따른다', () => {
+    assert.equal(resolveAdminCookieSecure({ protocol: 'http:' }), false);
+    assert.equal(resolveAdminCookieSecure({ protocol: 'https:' }), true);
+    assert.equal(resolveAdminCookieSecure({}), false);
+  });
+
+  it('리버스 프록시의 X-Forwarded-Proto 가 앱 서버 프로토콜보다 우선한다', () => {
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: 'https', protocol: 'http:' }), true);
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: 'http', protocol: 'https:' }), false);
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: 'HTTPS', protocol: 'http:' }), true);
+  });
+
+  it('프록시가 여러 겹이면 첫 값(클라이언트와 맞닿은 쪽)만 본다', () => {
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: 'https, http', protocol: 'http:' }), true);
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: 'http,https', protocol: 'https:' }), false);
+  });
+
+  it('빈 X-Forwarded-Proto 는 없는 것으로 본다', () => {
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: '', protocol: 'https:' }), true);
+    assert.equal(resolveAdminCookieSecure({ forwardedProto: ' , https', protocol: 'https:' }), true);
+  });
+
+  it('ADMIN_COOKIE_SECURE=true 면 평문 HTTP 요청에도 Secure 를 붙인다', () => {
+    for (const setting of ['true', 'TRUE', ' 1 ', 'yes', 'on']) {
+      assert.equal(resolveAdminCookieSecure({ setting, forwardedProto: 'http', protocol: 'http:' }), true, setting);
+    }
+  });
+
+  it('ADMIN_COOKIE_SECURE=false 면 HTTPS 요청에도 붙이지 않는다', () => {
+    for (const setting of ['false', 'False', '0', 'no', 'off']) {
+      assert.equal(resolveAdminCookieSecure({ setting, forwardedProto: 'https', protocol: 'https:' }), false, setting);
+    }
+  });
+
+  it('auto·빈 값·알 수 없는 값은 요청 프로토콜을 따른다', () => {
+    for (const setting of ['auto', '', '   ', 'maybe']) {
+      assert.equal(resolveAdminCookieSecure({ setting, protocol: 'http:' }), false, setting);
+      assert.equal(resolveAdminCookieSecure({ setting, forwardedProto: 'https', protocol: 'http:' }), true, setting);
+    }
+  });
+});
diff --git a/lib/adminSession.ts b/lib/adminSession.ts
index 00e2f30..9d90b45 100644
--- a/lib/adminSession.ts
+++ b/lib/adminSession.ts
@@ -60,3 +60,39 @@ export function verifyAdminSessionToken(token: string | undefined) {
 export function isAdminRequest(request: NextRequest) {
   return verifyAdminSessionToken(request.cookies.get(ADMIN_SESSION_COOKIE)?.value);
 }
+
+export interface AdminCookieSecureInput {
+  /** ADMIN_COOKIE_SECURE 환경 변수 값. true/false 로 강제하고, 비어 있거나 auto 면 요청 프로토콜을 따른다. */
+  setting?: string;
+  /** X-Forwarded-Proto 헤더. 리버스 프록시가 HTTPS 를 종단하면 'https' 가 온다. 여러 개면 첫 값만 본다. */
+  forwardedProto?: string | null;
+  /** 앱 서버가 직접 받은 요청의 프로토콜('https:' 또는 'http:'). */
+  protocol?: string;
+}
+
+const SECURE_ON = new Set(['true', '1', 'yes', 'on']);
+const SECURE_OFF = new Set(['false', '0', 'no', 'off']);
+
+/**
+ * 관리자 세션 쿠키에 Secure 속성을 붙일지 정한다.
+ * 브라우저는 평문 HTTP(localhost 제외)에서 Secure 쿠키를 저장하지 않으므로, HTTPS 없이 사내망에 띄운
+ * 운영 빌드에서 관리자 로그인이 되도록 기본은 요청이 실제로 HTTPS 로 왔을 때만 붙인다.
+ */
+export function resolveAdminCookieSecure(input: AdminCookieSecureInput) {
+  const setting = (input.setting ?? '').trim().toLowerCase();
+  if (SECURE_ON.has(setting)) return true;
+  if (SECURE_OFF.has(setting)) return false;
+
+  const forwarded = (input.forwardedProto ?? '').split(',')[0].trim().toLowerCase();
+  if (forwarded) return forwarded === 'https';
+
+  return (input.protocol ?? '').toLowerCase() === 'https:';
+}
+
+export function shouldSecureAdminCookie(request: NextRequest) {
+  return resolveAdminCookieSecure({
+    setting: process.env.ADMIN_COOKIE_SECURE,
+    forwardedProto: request.headers.get('x-forwarded-proto'),
+    protocol: request.nextUrl.protocol,
+  });
+}
