+import type { ActivitiesData } from './types.ts';
+
+/**
+ * 상황판 세 화면(표준·전광판·관리자)이 공유하는 SWR fetcher.
+ *
+ * GET /api/activities 는 파일을 읽지 못하면 500 과 함께 `activities: []` 가 담긴
+ * 정상 JSON 을 돌려준다. 그래서 `fetch(url).then(r => r.json())` 로는 파싱이 성공해
+ * SWR 의 error 가 비고 data 가 빈 배열로 채워진다 — 읽기 실패가 "등록된 작업 없음 /
+ * 0% 완료" 로 보이고, 상황실이 이것을 진짜 빈 상황판과 구분할 수 없다.
+ * 여기서 res.ok 를 보고 서버가 보낸 error 문구를 담아 throw 해야 화면이 둘을 가른다.
+ */
+export async function fetchActivityData(url: string): Promise<ActivitiesData> {
+  const res = await fetch(url);
+
+  if (!res.ok) {
+    const body = await res.json().catch(() => null) as { error?: string } | null;
+    throw new Error(body?.error ?? `상황판 데이터를 읽지 못했습니다. (HTTP ${res.status})`);
+  }
+
+  return await res.json() as ActivitiesData;
+}
