+    assert.equal(config.smtp_port, 2525);
+    assert.equal(config.security, 'auto');
+    assert.equal(config.timeout_seconds, 10);
+    assert.equal(config.from_name, 'Cutover 상황판');
+    // 이름을 일부러 비운 것은 존중한다.
+    assert.equal(normalizeMailConfig({ from_name: '' }).from_name, '');
+  });
+
+  it('비밀번호는 빠졌거나 빈 문자열이면 기존 값을 유지하고, password_clear 로만 지운다', () => {
+    const previous = { ...defaultMailConfig(), username: 'u', password: 'secret' };
+    assert.equal(normalizeMailConfig({ username: 'u' }, previous).password, 'secret');
+    assert.equal(normalizeMailConfig({ username: 'u', password: '' }, previous).password, 'secret');
+    assert.equal(normalizeMailConfig({ username: 'u', password: 'new' }, previous).password, 'new');
+    assert.equal(normalizeMailConfig({ username: 'u', password_clear: true }, previous).password, '');
+  });
+
+  it('base_url 의 끝 슬래시를 떼어낸다', () => {
+    assert.equal(normalizeMailConfig({ base_url: 'http://cutover.corp/' }).base_url, 'http://cutover.corp');
+  });
+});
+
+describe('비밀번호는 되읽히지 않는다', () => {
+  it('공개 모양에는 password 가 없고 password_set 만 있다', () => {
+    const shown = publicMailConfig({ ...defaultMailConfig(), password: 'secret' });
+    assert.equal('password' in shown, false);
+    assert.equal(shown.password_set, true);
+    assert.equal(JSON.stringify(shown).includes('secret'), false);
+    assert.equal(publicMailConfig(defaultMailConfig()).password_set, false);
+  });
+});
+
+describe('검증', () => {
+  it('켜면 릴레이 주소와 보내는 주소가 필요하다', () => {
+    const issues = validateMailConfig({ ...defaultMailConfig(), enabled: true });
+    assert.deepEqual(issues.map((issue) => issue.path).sort(), ['from_address', 'smtp_host']);
+    assert.equal(mailUnavailableReason({ ...defaultMailConfig(), enabled: true }), '릴레이 주소(mail.smtp_host)가 비어 있습니다.');
+  });
+
+  it('꺼져 있으면 값을 조금씩 채우며 저장할 수 있다', () => {
+    assert.deepEqual(validateMailConfig({ ...defaultMailConfig(), smtp_host: 'relay.corp' }), []);
+  });
+
+  it('주소 모양, 포트 범위, 사용자 이름 없는 비밀번호를 잡아낸다', () => {
+    const issues = validateMailConfig({
+      ...defaultMailConfig(),
+      smtp_port: 70000,
+      from_address: 'not-an-address',
+      base_url: 'cutover.corp',
+      password: 'x',
+      recipients: 'ok@corp.example, bad address',
+      timeout_seconds: 0,
+    });
+    assert.deepEqual(
+      issues.map((issue) => issue.path).sort(),
+      ['base_url', 'from_address', 'recipients', 'smtp_port', 'timeout_seconds', 'username'],
+    );
+  });
+});
+
+describe('받는 사람', () => {
+  it('쉼표·세미콜론·줄바꿈으로 나누고 대소문자만 다른 중복은 하나로 본다', () => {
+    assert.deepEqual(
+      parseRecipients('a@corp.example, B@corp.example;\n a@CORP.example \n'),
+      ['a@corp.example', 'B@corp.example'],
+    );
+  });
+});
+
+describe('이벤트 스위치', () => {
+  it('종류별로 끌 수 있고 시험 발송은 늘 허용된다', () => {
+    const config = { ...defaultMailConfig(), notify_task_completed: false };
+    assert.equal(allowsEvent(config, 'task.completed'), false);
+    assert.equal(allowsEvent(config, 'activity.delayed'), true);
+    assert.equal(allowsEvent(config, 'test'), true);
+  });
+});
