+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import type { Activity } from '../types.ts';
+import { defaultMailConfig } from './config.ts';
+import { composeNotification, detectMailChanges, renderBody, testNotification } from './events.ts';
+import { composeMessage, encodeHeaderText, formatAddress, normalizeBody } from './message.ts';
+
+function board(statuses: Record<string, Activity['status']>): Activity[] {
+  const base: Activity[] = [
+    { id: '1', parentId: null, level: 1, time: '21:00 ~ 22:00', title: '[Task#1] 서비스 중지', status: '대기' },
+    { id: '1-1', parentId: '1', level: 2, time: '22:00', title: '파킹페이지 게시', status: '대기' },
+    { id: '1-2', parentId: '1', level: 2, time: '미정', title: '트래픽 차단', status: '대기' },
+    { id: '2', parentId: null, level: 1, time: '23:00', title: '[Task#2] 네트워크', status: '대기' },
+  ];
+  return base.map((activity) => ({ ...activity, status: statuses[activity.id] ?? activity.status }));
+}
+
+const enabled = { ...defaultMailConfig(), enabled: true, smtp_host: 'relay', from_address: 'cutover@corp.example' };
+
+describe('메일감 고르기', () => {
+  it('상태가 그대로면 아무것도 고르지 않는다', () => {
+    assert.deepEqual(detectMailChanges(board({}), board({})), []);
+  });
+
+  it('제목·시간 편집이나 추가·삭제는 메일감이 아니다', () => {
+    const before = board({});
+    const after = board({}).map((activity) => ({ ...activity, title: `${activity.title} (수정)` })).slice(0, 3);
+    assert.deepEqual(detectMailChanges(before, after), []);
+  });
+
+  it('지연은 어느 단계든 잡고, 지연이 풀리면 해소로 잡는다', () => {
+    const delayed = detectMailChanges(board({}), board({ '1-1': '지연' }));
+    assert.equal(delayed.length, 1);
+    assert.equal(delayed[0].event, 'activity.delayed');
+
+    const cleared = detectMailChanges(board({ '1-1': '지연' }), board({ '1-1': '진행' }));
+    assert.deepEqual(cleared.map((change) => change.event), ['activity.delay_cleared']);
+
+    // 대기로 되돌린 것은 "해소" 가 아니라 취소다.
+    assert.deepEqual(detectMailChanges(board({ '1-1': '지연' }), board({ '1-1': '대기' })), []);
+  });
+
+  it('최상위 작업 완료는 잡고 하위 작업 완료는 잡지 않는다', () => {
+    assert.deepEqual(detectMailChanges(board({}), board({ '1-1': '완료' })), []);
+    const changes = detectMailChanges(board({ '1-1': '완료' }), board({ '1-1': '완료', '1-2': '완료', '1': '완료' }));
+    assert.deepEqual(changes.map((change) => change.event), ['task.completed']);
+  });
+
+  it('마지막 최상위 작업이 완료되면 훈련 완료도 함께 잡힌다', () => {
+    const changes = detectMailChanges(board({ '1': '완료' }), board({ '1': '완료', '2': '완료' }));
+    assert.deepEqual(changes.map((change) => change.event), ['task.completed', 'drill.completed']);
+    // 이미 다 끝난 상황판을 다시 저장해도 훈련 완료는 두 번 나가지 않는다.
+    assert.deepEqual(detectMailChanges(board({ '1': '완료', '2': '완료' }), board({ '1': '완료', '2': '완료' })), []);
+  });
+});
+
+describe('한 통으로 묶기', () => {
+  it('한 번의 조작이 만든 변화를 한 통으로 묶고 가장 급한 것이 제목이 된다', () => {
+    const changes = detectMailChanges(board({ '1-1': '지연' }), board({ '1-1': '완료', '1-2': '완료', '1': '완료', '2': '지연' }));
+    const notification = composeNotification(changes, enabled, '2026 훈련');
+    assert.ok(notification);
+    assert.equal(notification.event, 'activity.delayed');
+    assert.equal(notification.subject, '[2026 훈련] 지연: [Task#2] 네트워크 외 2건');
+    assert.equal(notification.lines.filter((line) => line.startsWith('[')).length, 3);
+    assert.match(notification.lines.join('\n'), /\[지연 해소\] 파킹페이지 게시 \(22:00\) — 지연 → 완료/);
+  });
+
+  it('스위치를 끄면 그 종류만 멎는다', () => {
+    const changes = detectMailChanges(board({}), board({ '1-1': '지연', '1': '완료' }));
+    const only = composeNotification(changes, { ...enabled, notify_activity_delayed: false }, '훈련');
+    assert.equal(only?.event, 'task.completed');
+    assert.equal(only?.subject, '[훈련] 작업 완료: [Task#1] 서비스 중지');
+    assert.equal(composeNotification(changes, { ...enabled, notify_activity_delayed: false, notify_task_completed: false }, '훈련'), null);
+  });
+
+  it('훈련 완료는 제목이 다르다', () => {
+    const changes = detectMailChanges(board({ '1': '완료' }), board({ '1': '완료', '2': '완료' }));
+    const notification = composeNotification(changes, { ...enabled, notify_task_completed: false }, '훈련');
+    assert.equal(notification?.subject, '[훈련] 모든 작업이 완료되었습니다');
+  });
+});
+
+describe('본문과 MIME', () => {
+  it('base_url 이 있을 때만 링크가 붙는다', () => {
+    const notification = testNotification('훈련');
+    assert.equal(renderBody(notification, enabled).includes('바로 열기'), false);
+    assert.match(renderBody(notification, { ...enabled, base_url: 'http://cutover.corp' }), /바로 열기: http:\/\/cutover\.corp\/admin/);
+  });
+
+  it('한글 제목과 이름은 RFC 2047 로 인코딩되고 ASCII 는 그대로 둔다', () => {
+    assert.equal(encodeHeaderText('SMTP test'), 'SMTP test');
+    assert.match(encodeHeaderText('[훈련] 지연: 아주 긴 제목이라 encoded-word 하나에 담기지 않는 경우를 봅니다'), /^=\?UTF-8\?B\?[A-Za-z0-9+/=]+\?=\r\n =\?UTF-8\?B\?/);
+    assert.equal(formatAddress({ name: 'Cutover', address: 'a@b.c' }), '"Cutover" <a@b.c>');
+    assert.match(formatAddress({ name: '상황판', address: 'a@b.c' }), /^=\?UTF-8\?B\?.+\?= <a@b\.c>$/);
+  });
+
+  it('줄 머리의 마침표를 겹쳐 본문이 DATA 를 일찍 끝내지 못하게 한다', () => {
+    assert.equal(normalizeBody('.hi\n.\nend'), '..hi\r\n..\r\nend\r\n');
+  });
+
+  it('메시지에 필요한 헤더가 모두 있고 본문 앞에 빈 줄이 있다', () => {
+    const raw = composeMessage({ from: { name: '', address: 'cutover@corp.example' }, to: 'ops@corp.example', subject: 'hello', body: 'body' });
+    const [headers, body] = raw.split('\r\n\r\n');
+    assert.match(headers, /^From: cutover@corp\.example\r\nTo: ops@corp\.example\r\nSubject: hello\r\nDate: .+\r\nMessage-ID: <.+@corp\.example>\r\nMIME-Version: 1\.0\r\nContent-Type: text\/plain; charset=UTF-8/);
+    assert.equal(body, 'body\r\n');
+  });
+});
