@@ -0,0 +1,156 @@
+/**
+ * 상황판 변경에서 메일감을 골라내는 순수 로직.
+ *
+ * 관리자 콘솔의 한 번의 조작(상태 클릭)은 연동 규칙 때문에 여러 액티비티를 한꺼번에 바꾼다 —
+ * 부모를 완료로 두면 자식이 모두 완료가 되고, 마지막 자식이 완료되면 부모도 완료가 된다.
+ * 그래서 저장 전후를 비교해 바뀐 것을 모으고, 한 통으로 묶는다. 한 번 눌렀는데 메일이
+ * 다섯 통 오면 사람들은 규칙을 만들어 통째로 버린다.
+ */
+import type { Activity } from '../types.ts';
+import { allowsEvent, type MailConfig, type MailEvent } from './config.ts';
+
+export interface ActivityChange {
+  event: Exclude<MailEvent, 'test'>;
+  activity: Activity;
+  /** 바뀌기 전 상태. 지연 해소는 어디서 왔는지가 문장에 들어간다. */
+  previousStatus: Activity['status'];
+}
+
+export interface DrillChange {
+  event: 'drill.completed';
+}
+
+export type MailChange = ActivityChange | DrillChange;
+
+/** 한 통의 메일. 본문은 발송 기록에 담지 않는다 — 제목과 수신자면 충분하다. */
+export interface Notification {
+  event: MailEvent;
+  subject: string;
+  lines: string[];
+  /** base_url 뒤에 붙는 경로. 메일 속 링크가 가리킬 화면. */
+  link: string;
+}
+
+/** 우선순위가 높은 것이 제목이 된다. 지연은 완료보다 급하다. */
+const EVENT_PRIORITY: Record<Exclude<MailEvent, 'test'>, number> = {
+  'activity.delayed': 0,
+  'drill.completed': 1,
+  'task.completed': 2,
+  'activity.delay_cleared': 3,
+};
+
+const EVENT_LABEL: Record<Exclude<MailEvent, 'test'>, string> = {
+  'activity.delayed': '지연',
+  'activity.delay_cleared': '지연 해소',
+  'task.completed': '작업 완료',
+  'drill.completed': '훈련 완료',
+};
+
+function isRoot(activity: Activity) {
+  return activity.parentId === null || activity.level === 1;
+}
+
+/** 저장 전후의 목록을 비교해 메일감이 되는 변화만 돌려준다. 새로 생기거나 지워진 항목은 세지 않는다. */
+export function detectMailChanges(before: Activity[], after: Activity[]): MailChange[] {
+  const previousById = new Map(before.map((activity) => [activity.id, activity]));
+  const changes: MailChange[] = [];
+
+  for (const activity of after) {
+    const previous = previousById.get(activity.id);
+    if (!previous || previous.status === activity.status) continue;
+
+    if (activity.status === '지연') {
+      changes.push({ event: 'activity.delayed', activity, previousStatus: previous.status });
+      continue;
+    }
+    if (previous.status === '지연' && activity.status !== '대기') {
+      changes.push({ event: 'activity.delay_cleared', activity, previousStatus: previous.status });
+    }
+    if (isRoot(activity) && activity.status === '완료') {
+      changes.push({ event: 'task.completed', activity, previousStatus: previous.status });
+    }
+  }
+
+  const rootsAfter = after.filter(isRoot);
+  const rootsBefore = before.filter(isRoot);
+  const allDone = (roots: Activity[]) => roots.length > 0 && roots.every((activity) => activity.status === '완료');
+  if (allDone(rootsAfter) && !allDone(rootsBefore)) {
+    changes.push({ event: 'drill.completed' });
+  }
+
+  return changes;
+}
+
+function describe(change: ActivityChange) {
+  const { activity } = change;
+  const where = activity.time && activity.time !== '미정' ? ` (${activity.time})` : '';
+  switch (change.event) {
+    case 'activity.delayed':
+      return `[지연] ${activity.title}${where} — ${change.previousStatus} → 지연`;
+    case 'activity.delay_cleared':
+      return `[지연 해소] ${activity.title}${where} — 지연 → ${activity.status}`;
+    case 'task.completed':
+      return `[완료] ${activity.title}${where}`;
+    default:
+      return activity.title;
+  }
+}
+
+/**
+ * 변화 목록을 한 통으로 묶는다. 스위치가 꺼진 종류는 빠지고, 남은 것이 없으면 null.
+ * 제목은 가장 급한 변화 하나로 짓고 나머지는 "외 n건" 으로 접는다.
+ */
+export function composeNotification(
+  changes: MailChange[],
+  config: MailConfig,
+  dashboardTitle: string,
+): Notification | null {
+  const allowed = changes.filter((change) => allowsEvent(config, change.event));
+  if (allowed.length === 0) return null;
+
+  const sorted = [...allowed].sort((left, right) => EVENT_PRIORITY[left.event] - EVENT_PRIORITY[right.event]);
+  const primary = sorted[0];
+  const others = sorted.length - 1;
+  const suffix = others > 0 ? ` 외 ${others}건` : '';
+
+  const headline = primary.event === 'drill.completed'
+    ? '모든 작업이 완료되었습니다'
+    : `${EVENT_LABEL[primary.event]}: ${primary.activity.title}`;
+
+  const lines: string[] = [`${dashboardTitle} 상황판에서 다음 변화가 있었습니다.`, ''];
+  for (const change of sorted) {
+    lines.push(change.event === 'drill.completed'
+      ? '[훈련 완료] 모든 최상위 작업이 완료 상태가 되었습니다.'
+      : `${describe(change)}`);
+  }
+
+  return {
+    event: primary.event,
+    subject: `[${dashboardTitle}] ${headline}${suffix}`,
+    lines,
+    link: '/pc',
+  };
+}
+
+/** 관리 화면의 시험 발송. 이 메일이 오면 릴레이 설정이 맞는 것이다. */
+export function testNotification(dashboardTitle: string): Notification {
+  return {
+    event: 'test',
+    subject: `[${dashboardTitle}] SMTP 발송 테스트`,
+    lines: [
+      '관리자 화면에서 보낸 테스트 메일입니다.',
+      '이 메일을 받았다면 SMTP 릴레이 설정이 정상입니다.',
+    ],
+    link: '/admin',
+  };
+}
+
+/** 본문 문장에 링크와 꼬리말을 붙인다. 링크는 base_url 이 있을 때만 들어간다. */
+export function renderBody(notification: Notification, config: MailConfig) {
+  const lines = [...notification.lines];
+  if (config.base_url && notification.link) {
+    lines.push('', `바로 열기: ${config.base_url}${notification.link.startsWith('/') ? '' : '/'}${notification.link}`);
+  }
+  lines.push('', '—', '이 메일은 Cutover 상황판의 메일 알림 설정에 따라 자동으로 발송되었습니다.');
+  return lines.join('\n');
+}
