+/**
+ * MIME 메시지 조립. 한글 제목과 이름은 RFC 2047 로 인코딩해 UTF-8 헤더를 모르는 릴레이와
+ * 클라이언트에서도 제대로 보이게 한다.
+ */
+import { randomBytes } from 'node:crypto';
+
+export interface MailAddress {
+  name: string;
+  address: string;
+}
+
+export interface MailMessage {
+  from: MailAddress;
+  to: string;
+  subject: string;
+  body: string;
+}
+
+const NEEDS_ENCODING = /[^\x20-\x7e]/;
+
+/** ASCII 가 아닌 헤더 값은 base64 encoded-word 로 감싼다. */
+export function encodeHeaderWord(value: string) {
+  return NEEDS_ENCODING.test(value) ? `=?UTF-8?B?${Buffer.from(value, 'utf-8').toString('base64')}?=` : value;
+}
+
+/** 제목처럼 긴 값은 encoded-word 하나가 75자를 넘지 않게 잘라 잇는다. */
+export function encodeHeaderText(value: string) {
+  if (!NEEDS_ENCODING.test(value)) return value;
+  const words: string[] = [];
+  const bytes = Buffer.from(value, 'utf-8');
+  // base64 45바이트 = 60자, 접두·접미를 더해도 75자 안이다. UTF-8 문자 경계에서만 자른다.
+  let start = 0;
+  while (start < bytes.length) {
+    let end = Math.min(start + 45, bytes.length);
+    while (end < bytes.length && (bytes[end] & 0xc0) === 0x80) end -= 1;
+    words.push(`=?UTF-8?B?${bytes.subarray(start, end).toString('base64')}?=`);
+    start = end;
+  }
+  return words.join('\r\n ');
+}
+
+export function formatAddress(address: MailAddress) {
+  const name = address.name.trim();
+  if (!name) return address.address;
+  const safe = NEEDS_ENCODING.test(name) ? encodeHeaderWord(name) : `"${name.replace(/["\\]/g, '\\$&')}"`;
+  return `${safe} <${address.address}>`;
+}
+
+/** 줄 끝을 CRLF 로 맞추고 줄 머리의 마침표를 겹쳐, 본문 한 줄이 DATA 를 일찍 끝내지 못하게 한다. */
+export function normalizeBody(body: string) {
+  let text = body.replace(/\r\n/g, '\n').replace(/\n/g, '\r\n');
+  if (text.startsWith('.')) text = `.${text}`;
+  text = text.replace(/\r\n\./g, '\r\n..');
+  if (!text.endsWith('\r\n')) text += '\r\n';
+  return text;
+}
+
+function messageId(domain: string) {
+  return `<${Date.now().toString(36)}.${randomBytes(8).toString('hex')}@${domain || 'cutover.local'}>`;
+}
+
+export function composeMessage(message: MailMessage, now: Date = new Date()) {
+  const domain = message.from.address.split('@')[1] ?? '';
+  const headers = [
+    `From: ${formatAddress(message.from)}`,
+    `To: ${message.to}`,
+    `Subject: ${encodeHeaderText(message.subject)}`,
+    `Date: ${now.toUTCString().replace(/GMT$/, '+0000')}`,
+    `Message-ID: ${messageId(domain)}`,
+    'MIME-Version: 1.0',
+    'Content-Type: text/plain; charset=UTF-8',
+    'Content-Transfer-Encoding: 8bit',
+    'Auto-Submitted: auto-generated',
+    'X-Cutover-Notification: 1',
+  ];
+  return `${headers.join('\r\n')}\r\n\r\n${normalizeBody(message.body)}`;
+}
