+});
+
+describe('SMTP 클라이언트', () => {
+  let relay: FakeRelay;
+  before(async () => { relay = await startFakeRelay(); });
+  after(async () => { await relay.close(); });
+
+  it('인증 없는 릴레이(auto)에 한 통을 보내고 본문의 마침표 겹침을 릴레이가 되돌린다', async () => {
+    await sendMail(optionsFor(relay), envelope());
+    assert.equal(relay.received.length, 1);
+    const mail = relay.received[0];
+    assert.equal(mail.from, 'cutover@corp.example');
+    assert.deepEqual(mail.to, ['ops@corp.example']);
+    assert.match(mail.data, /^From: =\?UTF-8\?B\?/);
+    assert.match(mail.data, /\r\n\r\n\.첫 줄\r\n둘째 줄/);
+  });
+
+  it('릴레이가 받는 사람을 거절하면 이유가 담긴 오류가 난다', async () => {
+    const strict = await startFakeRelay({ rejectRecipient: 'nobody@corp.example' });
+    try {
+      await assert.rejects(
+        sendMail(optionsFor(strict), envelope('nobody@corp.example')),
+        (error: unknown) => error instanceof SmtpError && /RCPT TO 실패: 550/.test(error.message),
