+    try {
+      await sendMail(optionsFor(relay, { username: 'mailer', password: 's3cret' }), envelope());
+      assert.deepEqual(relay.authAttempts, ['mailer:s3cret']);
+      assert.equal(relay.received.length, 1);
+
+      await assert.rejects(
+        sendMail(optionsFor(relay, { username: 'mailer', password: 'wrong-pw' }), envelope()),
