index 0000000..f8c5d87
--- /dev/null
+++ b/lib/mail/testing.ts
@@ -0,0 +1,162 @@
+/**
+ * 테스트용 가짜 SMTP 릴레이. 단위 테스트와 e2e 가 실제 릴레이 없이 클라이언트를 검증한다.
+ * 앱 코드는 이 모듈을 가져오지 않는다.
+ */
+import net from 'node:net';
+import type { AddressInfo } from 'node:net';
+
+export interface ReceivedMail {
+  from: string;
+  to: string[];
+  data: string;
+}
+
+export interface FakeRelayOptions {
+  /** 정하면 EHLO 에 AUTH PLAIN LOGIN 을 알리고 이 값만 받아들인다. */
+  auth?: { username: string; password: string };
+  /** 이 주소로의 RCPT 는 550 으로 거절한다. */
+  rejectRecipient?: string;
+  /** 인사 뒤 곧바로 연결을 끊는다(죽어 가는 릴레이 흉내). */
+  dropAfterGreeting?: boolean;
+}
+
+export interface FakeRelay {
+  host: string;
+  port: number;
+  received: ReceivedMail[];
+  /** 인증 시도에 쓰인 원문(base64 를 푼 값). 비밀번호가 실제로 전달됐는지 확인한다. */
+  authAttempts: string[];
+  close(): Promise<void>;
+}
+
+export async function startFakeRelay(options: FakeRelayOptions = {}): Promise<FakeRelay> {
+  const received: ReceivedMail[] = [];
+  const authAttempts: string[] = [];
+
+  const sockets = new Set<net.Socket>();
+  const server = net.createServer((socket) => {
+    sockets.add(socket);
+    socket.on('close', () => sockets.delete(socket));
+    socket.setEncoding('utf-8');
+    let buffer = '';
+    let inData = false;
+    let loginStep: 'user' | 'pass' | null = null;
+    let loginUser = '';
+    let current: ReceivedMail = { from: '', to: [], data: '' };
+    const reply = (text: string) => socket.write(`${text}\r\n`);
+
+    reply('220 fake-relay ESMTP');
+    if (options.dropAfterGreeting) {
+      socket.end(() => socket.destroy());
+      return;
+    }
+
+    const authenticated = (username: string, password: string) => {
+      authAttempts.push(`${username}:${password}`);
+      return options.auth !== undefined && options.auth.username === username && options.auth.password === password;
+    };
+
+    const handle = (line: string) => {
+      const upper = line.toUpperCase();
+      if (loginStep === 'user') {
+        loginUser = Buffer.from(line, 'base64').toString('utf-8');
+        loginStep = 'pass';
+        reply('334 UGFzc3dvcmQ6');
+        return;
+      }
+      if (loginStep === 'pass') {
+        loginStep = null;
+        reply(authenticated(loginUser, Buffer.from(line, 'base64').toString('utf-8')) ? '235 OK' : '535 Authentication failed');
+        return;
+      }
+      if (upper.startsWith('EHLO') || upper.startsWith('HELO')) {
+        const lines = ['250-fake-relay', '250-8BITMIME'];
+        if (options.auth) lines.push('250-AUTH PLAIN LOGIN');
+        lines.push('250 OK');
+        socket.write(`${lines.join('\r\n')}\r\n`);
+        return;
+      }
+      if (upper.startsWith('AUTH PLAIN')) {
+        const [, username = '', password = ''] = Buffer.from(line.slice('AUTH PLAIN '.length), 'base64').toString('utf-8').split('\u0000');
+        reply(authenticated(username, password) ? '235 OK' : '535 Authentication failed');
+        return;
+      }
+      if (upper.startsWith('AUTH LOGIN')) {
+        loginStep = 'user';
+        reply('334 VXNlcm5hbWU6');
+        return;
+      }
+      if (upper.startsWith('MAIL FROM:')) {
+        current = { from: line.slice('MAIL FROM:'.length).trim().replace(/^<|>$/g, ''), to: [], data: '' };
+        reply('250 OK');
+        return;
+      }
+      if (upper.startsWith('RCPT TO:')) {
+        const recipient = line.slice('RCPT TO:'.length).trim().replace(/^<|>$/g, '');
+        if (options.rejectRecipient && recipient === options.rejectRecipient) {
+          reply('550 No such user');
+          return;
+        }
+        current.to.push(recipient);
+        reply('250 OK');
+        return;
+      }
+      if (upper === 'DATA') {
+        inData = true;
+        reply('354 End data with <CR><LF>.<CR><LF>');
+        return;
+      }
+      if (upper === 'QUIT') {
+        reply('221 Bye');
+        socket.end();
+        return;
+      }
+      reply('500 Unknown command');
+    };
+
+    socket.on('data', (chunk: string) => {
+      buffer += chunk;
+      while (true) {
+        if (inData) {
+          const end = buffer.indexOf('\r\n.\r\n');
+          if (end === -1) return;
+          current.data = buffer.slice(0, end).replace(/\r\n\.\./g, '\r\n.');
+          buffer = buffer.slice(end + 5);
+          inData = false;
+          received.push(current);
+          reply('250 Queued');
+          continue;
+        }
+        const newline = buffer.indexOf('\r\n');
+        if (newline === -1) return;
+        const line = buffer.slice(0, newline);
+        buffer = buffer.slice(newline + 2);
+        handle(line);
+      }
+    });
+    socket.on('error', () => undefined);
+  });
+
+  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
+  const { port } = server.address() as AddressInfo;
+
+  return {
+    host: '127.0.0.1',
+    port,
+    received,
+    authAttempts,
+    close: () => new Promise<void>((resolve) => {
+      for (const socket of sockets) socket.destroy();
+      server.close(() => resolve());
+    }),
+  };
+}
+
+/** 아무도 듣지 않는 포트. 죽은 릴레이를 흉내 낼 때 쓴다. */
+export async function unusedPort(): Promise<number> {
+  const server = net.createServer();
+  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
+  const { port } = server.address() as AddressInfo;
+  await new Promise<void>((resolve) => server.close(() => resolve()));
+  return port;
+}
