+  constructor(issues: TrackingValidationIssue[]) {
+    super('추적 설정이 올바르지 않습니다.');
+    this.name = 'TrackingValidationError';
+    this.issues = issues;
+  }
+}
+
+/** 삽입할 <script> 하나. 문자열이 아니라 구조로 두어 React 가 속성을 이스케이프한다. */
+export interface SnippetScript {
+  src?: string;
+  inline?: string;
+  attributes: Record<string, string | true>;
+}
+
+export interface PolicySources {
+  scripts: string[];
+  connects: string[];
+  images: string[];
+}
+
+export function defaultTrackingConfig(): TrackingConfig {
+  return {
+    enabled: false,
+    provider: 'none',
+    momento_url: '',
+    momento_site_id: '',
+    momento_environment: 'prd',
+    momento_proxy: true,
+    measurement_id: '',
+    matomo_url: '',
+    matomo_site_id: '',
+    custom_snippet: '',
+    allowed_hosts: '',
+    include_admin: false,
+    placement: 'head',
+  };
+}
+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === 'object' && value !== null && !Array.isArray(value);
+}
+
+function stringField(value: unknown, fallback: string) {
+  return typeof value === 'string' ? value.trim() : fallback;
+}
+
+/** 저장된 값이 어떤 모양이든 완전한 설정으로 맞춘다. 모르는 값은 기본값으로 돌아간다. */
+export function normalizeTrackingConfig(value: unknown): TrackingConfig {
+  const defaults = defaultTrackingConfig();
+  if (!isRecord(value)) return defaults;
+
+  const provider = stringField(value.provider, defaults.provider).toLowerCase();
+  const placement = stringField(value.placement, defaults.placement).toLowerCase();
+
+  return {
+    enabled: value.enabled === true,
+    provider: (TRACKING_PROVIDERS as readonly string[]).includes(provider) ? provider as TrackingProvider : 'none',
