+
+/** 관리자가 손으로 적는 허용 출처. 정책 헤더에 그대로 들어가므로 모양을 엄격히 본다. */
+const ALLOWED_HOST_PATTERN = /^https?:\/\/(\*\.)?[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*(:\d{1,5})?$/;
+
+export function splitAllowedHosts(allowedHosts: string): string[] {
+  return allowedHosts
+    .split(/[,\s]+/)
+    .map((host) => host.trim().replace(/\/+$/, ''))
+    .filter((host) => host.length > 0);
