+
+/** 허용 목록에 출처를 더한다. 이미 있으면 그대로 둔다. */
+export function addAllowedHost(existing: string, origin: string): string {
+  const candidate = origin.trim().replace(/\/+$/, '');
+  if (!candidate) return existing;
+
+  const hosts = splitAllowedHosts(existing);
+  if (hosts.some((host) => host.toLowerCase() === candidate.toLowerCase())) return existing;
+  return [...hosts, candidate].join(', ');
