+
+/** 선택한 provider 에 필요한 값이 빠졌는지 본다. 꺼져 있으면 무엇이든 저장할 수 있다. */
+export function validateTrackingConfig(config: TrackingConfig): TrackingValidationIssue[] {
+  const issues: TrackingValidationIssue[] = [];
+
+  if (new TextEncoder().encode(config.custom_snippet).length > MAX_SNIPPET_BYTES) {
+    issues.push({ path: 'custom_snippet', message: `추적 코드는 ${MAX_SNIPPET_BYTES / 1024}KB 를 넘을 수 없습니다.` });
+  }
+
+  const hosts = splitAllowedHosts(config.allowed_hosts);
+  if (hosts.length > MAX_ALLOWED_HOSTS) {
+    issues.push({ path: 'allowed_hosts', message: `허용 출처는 최대 ${MAX_ALLOWED_HOSTS}개까지 적을 수 있습니다.` });
+  }
