+export function isAdminPath(pathname: string) {
+  return pathname === '/admin' || pathname.startsWith('/admin/');
+}
+
+/** 화면이 아닌 경로. 스니펫도 붙지 않고 정책도 더 좁다. */
+export function isNonPagePath(pathname: string) {
+  return pathname.startsWith('/api/')
+    || pathname === MOMENTO_PROXY_PATH
+    || pathname.startsWith(`${MOMENTO_PROXY_PATH}/`)
+    || pathname.startsWith('/_next/');
+}
+
+/** 이 경로의 페이지에 스니펫을 붙여야 하는가. */
+export function isTrackingActive(config: TrackingConfig, pathname: string) {
+  if (!config.enabled || config.provider === 'none') return false;
+  if (isNonPagePath(pathname)) return false;
+  if (!config.include_admin && isAdminPath(pathname)) return false;
+  return renderSnippetScripts(config).length > 0;
+}
+
+function momentoBase(config: TrackingConfig) {
+  return config.momento_url.replace(/\/+$/, '');
+}
+
+/** provider 별 <script> 목록. nonce 는 렌더링할 때 모든 태그에 붙는다. */
+export function renderSnippetScripts(config: TrackingConfig): SnippetScript[] {
+  switch (config.provider) {
+    case 'momento': {
+      const base = momentoBase(config);
+      const siteId = config.momento_site_id;
+      if (!base || !siteId) return [];
