+  }
+}
+
+const SCRIPT_TAG_PATTERN = /<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi;
+const ATTRIBUTE_PATTERN = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'<>`]+)))?/g;
+
+/**
+ * 붙여 넣은 스니펫에서 <script> 태그만 뽑아 구조로 바꾼다. 그 밖의 마크업(noscript 등)은
+ * 버린다 — 정책이 막는 것은 스크립트이고, 그것만 nonce 를 달아 다시 그릴 수 있다.
+ * on* 속성과 기존 nonce 는 버린다. 인라인 핸들러는 어차피 정책에 막히고 nonce 는 요청마다 새로 단다.
+ */
+export function parseSnippetScripts(snippet: string): SnippetScript[] {
+  const scripts: SnippetScript[] = [];
+  for (const match of snippet.matchAll(SCRIPT_TAG_PATTERN)) {
+    const attributes: Record<string, string | true> = {};
+    let src: string | undefined;
+    for (const attribute of match[1].matchAll(ATTRIBUTE_PATTERN)) {
+      const name = attribute[1].toLowerCase();
+      const value = attribute[2] ?? attribute[3] ?? attribute[4];
+      if (name.startsWith('on') || name === 'nonce') continue;
+      if (name === 'src') {
+        src = value?.trim() || undefined;
+        continue;
+      }
+      attributes[name] = value === undefined ? true : value;
+    }
+    const inline = match[2].trim();
+    if (!src && !inline) continue;
+    scripts.push(src ? { src, attributes } : { inline, attributes });
+  }
+  return scripts;
+}
+
+function escapeAttribute(value: string) {
+  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
+}
+
+/**
+ * <script> 목록을 nonce 를 달아 HTML 문자열로 만든다. body 끝에 넣을 때 쓴다 — React 는
+ * async 외부 스크립트 요소를 head 로 끌어올리므로, 관리자가 고른 자리를 지키려면 문자열로 심어야 한다.
+ */
+export function serializeSnippetScripts(scripts: SnippetScript[], nonce: string) {
+  return scripts.map((script) => {
+    const attributes = [`nonce="${escapeAttribute(nonce)}"`, 'data-tracking-snippet=""'];
+    if (script.src) attributes.push(`src="${escapeAttribute(script.src)}"`);
+    for (const [name, value] of Object.entries(script.attributes)) {
+      if (!/^[a-z][a-z0-9-]*$/.test(name)) continue;
+      attributes.push(value === true ? name : `${name}="${escapeAttribute(value)}"`);
+    }
+    const inline = (script.inline ?? '').replace(/<\/(script)/gi, '<\\/$1');
+    return `<script ${attributes.join(' ')}>${inline}</script>`;
+  }).join('\n');
+}
+
+const URL_BOUNDARY = /["'`<>\s),;\\+]/;
+
+/**
+ * 스니펫 문자열에 적힌 모든 http(s) 출처. 추적 도구는 자기 주소를 로더 안에 적어 두므로
+ * 여기서 읽으면 관리자가 정책 오류를 호스트 이름으로 번역해 손으로 넣을 필요가 없다.
+ */
+export function snippetOrigins(snippet: string): string[] {
+  const origins: string[] = [];
+  const seen = new Set<string>();
+  const lower = snippet.toLowerCase();
+  let index = 0;
+  while (index < snippet.length) {
+    const start = lower.indexOf('http', index);
+    if (start < 0) break;
+    let end = start;
+    while (end < snippet.length && !URL_BOUNDARY.test(snippet[end])) end += 1;
+    index = end > start ? end : start + 4;
+    const origin = originOf(snippet.slice(start, end));
+    if (!origin || seen.has(origin)) continue;
+    seen.add(origin);
+    origins.push(origin);
+  }
+  return origins;
+}
+
+/** 스니펫이 필요로 하는 추가 출처. provider 가 정해진 경우는 정책 지식 없이도 맞게 나온다. */
+export function policySources(config: TrackingConfig): PolicySources {
+  const sources: PolicySources = { scripts: [], connects: [], images: [] };
+  const addEverywhere = (origin: string) => {
+    for (const group of [sources.scripts, sources.connects, sources.images]) {
+      if (!group.includes(origin)) group.push(origin);
+    }
+  };
+
+  switch (config.provider) {
+    case 'momento': {
+      const origin = originOf(config.momento_url);
+      // 같은 오리진 프록시를 쓰면 외부 출처가 정책에 아예 등장하지 않는다.
+      if (origin && !config.momento_proxy) addEverywhere(origin);
+      break;
+    }
+    case 'ga4':
+    case 'gtm':
+      sources.scripts.push('https://www.googletagmanager.com');
+      sources.connects.push('https://www.google-analytics.com', 'https://analytics.google.com', 'https://*.google-analytics.com');
+      sources.images.push('https://www.google-analytics.com', 'https://www.googletagmanager.com');
+      break;
+    case 'matomo': {
+      const origin = originOf(config.matomo_url);
+      if (origin) addEverywhere(origin);
+      break;
+    }
+    case 'custom':
+      for (const origin of snippetOrigins(config.custom_snippet)) addEverywhere(origin);
+      break;
+    default:
+      break;
+  }
+
+  for (const host of splitAllowedHosts(config.allowed_hosts)) {
+    if (ALLOWED_HOST_PATTERN.test(host)) addEverywhere(host);
+  }
+
+  return sources;
+}
+
+/** 정책 항목(https://*.example.com 포함)이 이 출처를 허용하는가. */
+export function sourceAllows(pattern: string, origin: string) {
+  const normalizedPattern = pattern.toLowerCase().replace(/\/+$/, '');
+  const normalizedOrigin = origin.toLowerCase().replace(/\/+$/, '');
+  if (normalizedPattern === normalizedOrigin) return true;
+
+  const star = normalizedPattern.indexOf('*.');
+  if (star < 0) return false;
+  const scheme = normalizedPattern.slice(0, star);
+  const suffix = normalizedPattern.slice(star + 1);
+  return normalizedOrigin.startsWith(scheme) && normalizedOrigin.endsWith(suffix);
+}
+
+export interface PolicyOptions {
+  /** 개발 서버는 React 가 eval 로 서버 스택을 복원하고 HMR 이 웹소켓을 쓴다. */
+  development?: boolean;
+}
+
+/**
+ * 화면 경로의 정책. 추적이 꺼져 있으면 nonce 와 앱 오리진만 남는다 — 'unsafe-inline' 은
+ * 어디에도 넣지 않는다. 한 번 넣으면 추적을 끈 뒤에도 정책은 느슨한 채로 남기 때문이다.
+ */
+export function buildPagePolicy(config: TrackingConfig, pathname: string, nonce: string, options: PolicyOptions = {}) {
+  const scripts = ['\'self\'', `'nonce-${nonce}'`];
+  const connects = ['\'self\''];
+  const images = ['\'self\'', 'data:', 'blob:'];
+  if (options.development) {
+    scripts.push('\'unsafe-eval\'');
+    connects.push('ws:', 'wss:');
+  }
+
+  const active = isTrackingActive(config, pathname);
+  if (active) {
+    const extra = policySources(config);
+    scripts.push(...extra.scripts);
+    connects.push(...extra.connects);
+    images.push(...extra.images);
+  }
+
+  const directives = [
+    'default-src \'self\'',
+    `script-src ${scripts.join(' ')}`,
+    // 화면은 style 속성(React 인라인 스타일)을 쓴다. 스크립트가 아니므로 정책이 막는 대상이 아니다.
+    'style-src \'self\' \'unsafe-inline\'',
+    `img-src ${images.join(' ')}`,
+    'font-src \'self\' data:',
+    `connect-src ${connects.join(' ')}`,
+    'object-src \'none\'',
+    'base-uri \'self\'',
+    'form-action \'self\'',
+    'frame-ancestors \'self\'',
+  ];
+  if (active) {
+    // 추적이 켜진 동안만 브라우저에게 무엇을 막았는지 알려 달라고 한다.
+    directives.push(`report-uri ${CSP_REPORT_PATH}`);
+  }
+  return directives.join('; ');
+}
+
+/** API·프록시 같은 비화면 경로의 정책. 그릴 것이 없으니 전부 막는다. */
+export const NON_PAGE_POLICY = 'default-src \'none\'; frame-ancestors \'none\'';
+
+export function extractOrigin(raw: string) {
+  return originOf(raw);
+}
