+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import type { Activity } from './types.ts';
+import { addActivity, collectDescendantIds, deleteActivity, initialActivities } from './treeUtils.ts';
+import { validateActivityImport } from './activityData.ts';
+
+function node(id: string, parentId: string | null, level = parentId ? 2 : 1): Activity {
+  return { id, parentId, level, time: '미정', title: id, status: '대기' };
+}
+
+// 업로드한 activity.json 처럼 id 가 `부모-번호` 꼴이 아닌 3단 트리
+const arbitraryTree: Activity[] = [
+  node('net', null),
+  node('vlan', 'net'),
+  node('vlan-check', 'vlan', 3),
+  node('db', null),
+  node('dbswitch', 'db'),
+];
+
+describe('addActivity', () => {
+  it('120자 ID 부모 아래 자식과 그 아래 손자를 추가해도 업로드 검증을 통과한다', () => {
+    const parent = node('p'.repeat(120), null);
+    const original = [parent];
+    assert.deepEqual(validateActivityImport({ activities: original }).activities, original);
+
+    const withChild = addActivity(original, parent.id);
+    assert.deepEqual(validateActivityImport({ activities: withChild }).activities, withChild);
+    const child = withChild[1];
+    assert.equal(typeof child.id, 'string');
+    assert.ok(child.id.length > 0 && child.id.length <= 120);
+    assert.equal(child.parentId, parent.id);
+    assert.equal(child.level, parent.level + 1);
+
