@@ -0,0 +1,47 @@
+import { randomBytes } from 'node:crypto';
+import { NextRequest, NextResponse } from 'next/server';
+import { buildPagePolicy, isNonPagePath, isTrackingActive, NON_PAGE_POLICY } from '@/lib/tracking/core';
+import { readTrackingConfig } from '@/lib/tracking/store';
+
+/**
+ * 모든 응답에 콘텐츠 보안 정책을 단다. 화면에는 요청마다 새 nonce 를 만들어 정책에
+ * 넣고 요청 헤더로도 넘긴다 — Next 는 요청 헤더의 정책에서 nonce 를 읽어 자기 스크립트에
+ * 붙이고, 레이아웃은 x-nonce 로 같은 값을 받아 추적 스니펫에 단다.
+ */
+export async function proxy(request: NextRequest) {
+  const { pathname } = request.nextUrl;
+
+  if (isNonPagePath(pathname)) {
+    const response = NextResponse.next();
+    response.headers.set('Content-Security-Policy', NON_PAGE_POLICY);
+    return response;
+  }
+
+  const nonce = randomBytes(16).toString('base64');
+  const config = await readTrackingConfig();
+  const policy = buildPagePolicy(config, pathname, nonce, {
+    development: process.env.NODE_ENV === 'development',
+  });
+
+  const requestHeaders = new Headers(request.headers);
+  requestHeaders.set('x-nonce', nonce);
+  requestHeaders.set('x-tracking-active', isTrackingActive(config, pathname) ? '1' : '0');
+  requestHeaders.set('Content-Security-Policy', policy);
+
+  const response = NextResponse.next({ request: { headers: requestHeaders } });
+  response.headers.set('Content-Security-Policy', policy);
+  return response;
+}
+
+export const config = {
+  matcher: [
+    {
+      // 정적 자산과 링크 프리페치에는 정책이 필요 없다.
+      source: '/((?!_next/static|_next/image|favicon.ico).*)',
+      missing: [
+        { type: 'header', key: 'next-router-prefetch' },
+        { type: 'header', key: 'purpose', value: 'prefetch' },
+      ],
+    },
+  ],
+};
