export const runtime = 'nodejs';

/** 신고 본문은 작다. 이보다 큰 것은 신고가 아니다. */
const MAX_REPORT_BYTES = 16 * 1024;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function stringOf(record: Record<string, unknown>, ...keys: string[]) {
  for (const key of keys) {
    const value = record[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

function pageOf(documentUri: string) {
  try {
    return new URL(documentUri).pathname;
  } catch {
    return documentUri.slice(0, 200);
  }
}

/**
 * 브라우저의 CSP 위반 신고(report-uri). 인증이 없다 — 방문자 브라우저가 보내는 것이다.
 * 추적이 꺼져 있으면 정책에 report-uri 가 없으니 보통 오지 않지만, 와도 기록하지 않는다.
 */
export async function POST(request: NextRequest) {
  const config = await readTrackingConfig();
  if (!config.enabled) return new NextResponse(null, { status: 204 });

  const contentLength = Number(request.headers.get('content-length'));
  if (Number.isFinite(contentLength) && contentLength > MAX_REPORT_BYTES) {
    return new NextResponse(null, { status: 413 });
  }

  let body: unknown;
  try {
    const text = await request.text();
    if (text.length > MAX_REPORT_BYTES) return new NextResponse(null, { status: 413 });
    body = JSON.parse(text);
  } catch {
    return new NextResponse(null, { status: 400 });
  }

  // report-uri 는 { "csp-report": {...} } 로, Reporting API 는 [{ body: {...} }] 로 온다.
  const reports: unknown[] = Array.isArray(body) ? body.map((item) => (isRecord(item) ? item.body : null)) : [body];
  const recorder = getViolationRecorder();
  for (const report of reports) {
    if (!isRecord(report)) continue;
    const detail = isRecord(report['csp-report']) ? report['csp-report'] : report;
    const blocked = stringOf(detail, 'blocked-uri', 'blockedURL', 'blockedURI');
    const directive = stringOf(detail, 'effective-directive', 'effectiveDirective', 'violated-directive', 'violatedDirective');
    if (!blocked) continue;
    recorder.record(blocked, directive, pageOf(stringOf(detail, 'document-uri', 'documentURL', 'documentURI')));
  }

  return new NextResponse(null, { status: 204 });
}

