/bin/bash -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import vm from 'node:vm';
import { validateActivityImport, ActivityImportValidationError } from './lib/activityData.ts';
import { addActivity } from './lib/treeUtils.ts';
const require = createRequire(import.meta.url);
const ts = require('typescript');
const React = require('react');
const { renderToStaticMarkup } = require('react-dom/server');
const source = fs.readFileSync('app/admin/page.tsx', 'utf8');
const start = source.indexOf('const submitActivityChange =');
const end = source.indexOf('const saveDashboardTitle =', start);
const handler = ts.transpile(source.slice(start, end), { target: ts.ScriptTarget.ES2022 });
const span = source.match(/<span className=\"whitespace-pre-line\">\\{saveError\\}<\\/span>/)?.[0];
assert.ok(span);
const renderCode = ts.transpile("'`const rendered = (${span});`, { jsx: ts.JsxEmit.React, target: ts.ScriptTarget.ES2022 });
let payload, savedError;
const sandbox = { React, fetch: async () => ({ ok: false, status: 400, json: async () => payload }), setSaveError: value => { savedError = value; }, handleUnauthorized: () => assert.fail('"'unexpected 401'), mutate: () => assert.fail('unexpected success') };
vm.createContext(sandbox);
vm.runInContext(handler, sandbox);
async function display(details) {
  payload = { error: '검증 실패', details };
  await vm.runInContext('submitActivityChange({})', sandbox);
  sandbox.saveError = savedError;
  return renderToStaticMarkup(vm.runInContext("'`(() => { ${renderCode}; return rendered; })()`, sandbox));
}
const malicious = '"'<img src=x onerror=alert(1)><script>alert(1)</script>';
const html = await display([null, {}, { path: 'title', message: malicious }, { path: 42, message: 'ignore-me' }]);
assert.ok(html.includes('&lt;img'));
assert.ok("'!html.includes('"'<img'));
assert.ok("'!html.includes('"'<script'));
assert.ok("'!html.includes('"'ignore-me'));
console.log('PASS: actual handler and JSX span escape HTML and filter mixed invalid details (server rendering)');
const chain = Array.from({ length: 50 }, (_, i) => ({ id: "'`depth-${i}`, parentId: i ? `depth-${i-1}` : null, level: i+1, time: '"'00:00', title: 'test', status: '대기' }));
const roots = Array.from({ length: 5000 }, (_, i) => ({ ...chain[0], id: "'`root-${i}` }));
for (const [name, activities, expected] of [
  ['"'depth 51', addActivity(chain, 'depth-49'), 'level은 1 이상 50 이하'],
  ['count 5001', addActivity(roots, null), '최대 5,000개'],
]) {
  let issues;
  try { validateActivityImport({ activities }); assert.fail('invalid data accepted'); }
  catch (error) { assert.ok(error instanceof ActivityImportValidationError); issues = error.issues; }
  await display(issues);
  assert.ok(savedError.includes(expected));
  console.log("'`PASS: ${name} validator details survive actual handler`);
}
NODE'

